INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetes — Diagnosis & Type 1 Management','easy','mcq','Which fasting plasma glucose (FPG) value confirms a diagnosis of diabetes mellitus when measured on two separate occasions in an asymptomatic patient?','["A. >=6.1 mmol/L","B. >=7.0 mmol/L","C. >=8.0 mmol/L","D. >=11.1 mmol/L"]','B','FPG >=7.0 mmol/L (126 mg/dL) on two separate occasions confirms diabetes mellitus in an asymptomatic patient. A single value >=7.0 mmol/L with classic symptoms is also diagnostic. FPG 6.1-6.9 mmol/L constitutes impaired fasting glucose (pre-diabetes). The WHO/ADA diagnostic criteria also include 2-hr OGTT >=11.1 mmol/L, HbA1c >=48 mmol/mol, or random glucose >=11.1 with symptoms.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetes — Diagnosis & Type 1 Management','easy','mcq','A 2-hour plasma glucose of 13.5 mmol/L on an oral glucose tolerance test (OGTT) is interpreted as:','["A. Normal glucose tolerance (<7.8 mmol/L)","B. Impaired glucose tolerance (7.8-11.0 mmol/L)","C. Diagnostic of diabetes mellitus (>=11.1 mmol/L)","D. Requires repeat testing before diagnosis in all cases"]','C','A 2-hour OGTT plasma glucose >=11.1 mmol/L (200 mg/dL) is diagnostic of diabetes mellitus. Values 7.8-11.0 mmol/L represent impaired glucose tolerance (pre-diabetes). A value <7.8 mmol/L at 2 hours is normal. In symptomatic patients, one reading is sufficient for diagnosis; asymptomatic patients need confirmation on a second day.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetes — Diagnosis & Type 1 Management','medium','mcq','A 19-year-old presents with 3-week history of polyuria, polydipsia, and 5 kg weight loss. Random blood glucose is 17.2 mmol/L and urine ketones are 3+. The MOST appropriate initial management is:','["A. Start metformin 500 mg BD and dietary modification","B. Prescribe an SGLT-2 inhibitor (empagliflozin)","C. Initiate basal-bolus insulin regimen with urgent endocrinology referral","D. Lifestyle modification and repeat glucose in 3 months"]','C','This presentation is classic new-onset Type 1 DM: young age, acute onset, significant ketones, significant weight loss. Insulin replacement with a basal-bolus regimen (long-acting basal analogue + rapid-acting analogue before meals) is mandatory. Metformin and SGLT-2 inhibitors are not appropriate for Type 1 DM. Delay in insulin initiation risks progression to DKA.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetes — Diagnosis & Type 1 Management','medium','mcq','Which HbA1c value meets the diagnostic threshold for diabetes mellitus according to WHO/ADA criteria?','["A. 42 mmol/mol (6.0%)","B. 45 mmol/mol (6.3%)","C. 47 mmol/mol (6.4%)","D. 48 mmol/mol (6.5%)"]','D','HbA1c >=48 mmol/mol (>=6.5%) is diagnostic of diabetes mellitus when measured by a standardised, certified assay. HbA1c 39-47 mmol/mol (5.7-6.4%) indicates pre-diabetes. In asymptomatic patients, a repeat confirmatory test on a second day is required. HbA1c is unreliable in conditions affecting red cell turnover (haemolytic anaemia, haemoglobinopathies, iron deficiency).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetes — Diagnosis & Type 1 Management','medium','mcq','A 16-year-old with Type 1 DM develops fever and vomiting during a respiratory infection. Capillary glucose reads 19 mmol/L and ketones are 2+. Which sick-day rule is MOST important?','["A. Continue insulin and check blood ketones every 1-2 hours","B. Withhold insulin until able to eat normally to prevent hypoglycaemia","C. Switch to short-acting insulin only during illness","D. Restrict all carbohydrate intake to bring glucose down"]','A','Sick-day rules for Type 1 DM: NEVER stop insulin -- illness causes insulin resistance via counter-regulatory hormones (cortisol, glucagon, adrenaline), raising glucose and risking DKA. Monitor ketones every 1-2 hours. Give extra rapid-acting correction doses if glucose is high and ketones rising. If vomiting prevents oral intake or ketones are >3 mmol/L, attend hospital urgently for IV fluid and insulin.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetes — Diagnosis & Type 1 Management','hard','mcq','A Type 1 DM patient on insulin glargine 24 units nocte and lispro with meals has HbA1c 72 mmol/mol with fasting glucoses consistently 12-14 mmol/L despite good post-meal control. The BEST adjustment is:','["A. Add metformin 500 mg BD to reduce insulin requirements","B. Increase insulin glargine by 2 units every 3 days until fasting glucose is 4-7 mmol/L","C. Switch to twice-daily premixed 70/30 insulin","D. Add pioglitazone as insulin sensitiser"]','B','Persistently elevated fasting glucose in a basal-bolus regimen indicates inadequate BASAL insulin (glargine). Adjust basal insulin: increase glargine by 2 units every 3 days (standard titration algorithm) until fasting glucose is consistently 4-7 mmol/L. Pre-meal bolus adjustments address post-prandial, not fasting, hyperglycaemia. Premixed insulins offer less flexibility in Type 1 DM.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetes — Diagnosis & Type 1 Management','easy','mcq','Which is the gold-standard insulin regimen for Type 1 diabetes mellitus?','["A. Once-daily long-acting basal insulin only","B. Twice-daily premixed insulin 70/30","C. Basal-bolus: long-acting insulin once daily + rapid-acting analogue before each meal","D. Oral hypoglycaemic agents with supplemental insulin PRN"]','C','Basal-bolus therapy best mimics physiological insulin secretion: basal analogue (glargine, detemir, degludec) provides background insulin; rapid-acting analogue (lispro, aspart, glulisine) covers meal-related glucose excursions. This regimen allows flexibility in meal timing, individual dose adjustment, and achieves the best glycaemic control. Continuous subcutaneous insulin infusion (CSII/pump) is an alternative for selected patients.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetes — Diagnosis & Type 1 Management','medium','mcq','A patient with classic symptoms of polyuria, polydipsia, and weight loss has a random plasma glucose of 13.4 mmol/L. Which statement is CORRECT?','["A. A second confirmatory test is required before diagnosis can be made","B. HbA1c must be obtained before confirming the diagnosis","C. The result must be repeated fasting to be valid for diagnosis","D. This single result with classic symptoms is sufficient to diagnose diabetes mellitus"]','D','When classic symptoms of diabetes are present (polyuria, polydipsia, unexplained weight loss), a single random plasma glucose >=11.1 mmol/L is sufficient for diagnosis -- no repeat test is required. This is a key clinical distinction: symptoms present + one abnormal result = diabetes. Asymptomatic patients require two abnormal values on separate occasions.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetes — Diagnosis & Type 1 Management','hard','mcq','A 22-year-old on insulin pump (CSII) develops glucose 22 mmol/L and ketones 3+ during illness; the infusion set was last changed 4 days ago. The PRIORITY action is:','["A. Give subcutaneous rapid-acting insulin injection (bypassing the pump) and replace the infusion set immediately","B. Increase the basal rate on the pump by 50%","C. Give a large correction bolus via the pump","D. Add oral metformin to reduce glucose temporarily"]','A','Unexplained hyperglycaemia with ketones in a pump user strongly suggests cannula occlusion/failure -- a common cause of DKA in CSII users. Priority: give subcutaneous rapid-acting insulin to bypass the potentially blocked cannula, then replace the infusion set. Continuing to attempt boluses through a blocked cannula risks progressive ketosis. This patient needs urgent hospital assessment for evolving DKA. Infusion sets should be changed every 2-3 days.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetes — Diagnosis & Type 1 Management','medium','mcq','Routine screening of an asymptomatic adult reveals FPG 6.5 mmol/L. Which action is MOST appropriate?','["A. Start metformin immediately -- glucose is in the diabetic range","B. Repeat fasting plasma glucose on a separate day to confirm the result","C. Diagnose diabetes and initiate insulin therapy","D. No action needed -- this is within normal limits"]','B','An FPG of 6.5 mmol/L is below the diabetes diagnostic threshold (>=7.0 mmol/L) -- this represents impaired fasting glucose (IFG). In asymptomatic patients, two abnormal values are required to diagnose diabetes. Repeating the test confirms or refutes the diagnosis. Confirmed IFG requires lifestyle intervention (diet, exercise, weight loss) and close monitoring for progression to diabetes (annual review).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetes — Type 2 Management','easy','mcq','According to the Ghana Standard Treatment Guidelines 2017, which drug is the FIRST-LINE pharmacological treatment for Type 2 diabetes mellitus?','["A. Metformin","B. Glibenclamide (sulfonylurea)","C. Insulin glargine","D. Sitagliptin (DPP-4 inhibitor)"]','A','Ghana STG 2017 and all major international guidelines (ADA, NICE, WHO) recommend metformin as first-line pharmacotherapy for Type 2 DM, initiated at 500 mg BD with meals, titrated to 1-2 g/day. Metformin reduces hepatic glucose production (AMPK activation), improves insulin sensitivity, is weight-neutral to weight-reducing, rarely causes hypoglycaemia, and has evidence for cardiovascular benefit (UKPDS). HbA1c target: <53 mmol/mol (<7%).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetes — Type 2 Management','easy','mcq','What is the standard HbA1c target for most non-elderly adults with Type 2 diabetes mellitus without cardiovascular disease?','["A. <48 mmol/mol (6.5%)","B. <53 mmol/mol (7.0%)","C. <64 mmol/mol (8.0%)","D. <75 mmol/mol (9.0%)"]','B','HbA1c <53 mmol/mol (<7.0%) is the standard target for most non-elderly adults with Type 2 DM. Tighter targets (<48 mmol/mol) may suit young patients with short disease duration without hypoglycaemia risk. Relaxed targets (<64-75 mmol/mol) are appropriate for frail elderly patients, those with hypoglycaemia unawareness, multiple comorbidities, or limited life expectancy. Ghana STG 2017 endorses this target.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetes — Type 2 Management','medium','mcq','A 55-year-old man with Type 2 DM is on maximum-dose metformin (2 g/day). HbA1c remains 68 mmol/mol after 6 months. He has no cardiovascular disease. The MOST appropriate next step is:','["A. Switch from metformin to insulin immediately","B. Add a second oral agent (sulfonylurea, DPP-4i, SGLT-2i, or GLP-1 RA) based on patient profile","C. Add pioglitazone for all patients as second-line","D. Perform bariatric surgery as next step"]','C','When metformin monotherapy fails, a second agent is added. In resource-limited settings per Ghana STG, glibenclamide (sulfonylurea) is a cost-effective second agent. In patients with established CVD, SGLT-2 inhibitors or GLP-1 RAs with proven CV benefit are preferred. In obese patients, GLP-1 RAs (weight loss). Choice depends on: CVD status, weight, hypoglycaemia risk, cost, and tolerability. Sulfonylureas are widely used in Ghana and other African countries due to cost-effectiveness.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetes — Type 2 Management','medium','mcq','A 48-year-old obese woman (BMI 36 kg/m2) with Type 2 DM has HbA1c 62 mmol/mol on metformin. She has no CVD but wishes to lose weight. The BEST add-on therapy is:','["A. Glibenclamide (sulfonylurea -- associated with weight gain)","B. Pioglitazone (thiazolidinedione -- causes weight gain and fluid retention)","C. Sitagliptin (DPP-4 inhibitor -- weight neutral)","D. Semaglutide (GLP-1 receptor agonist -- significant weight loss + HbA1c reduction)"]','D','GLP-1 receptor agonists (semaglutide, liraglutide) provide 5-15% body weight reduction alongside HbA1c lowering, making them ideal for obese patients with T2DM. Semaglutide (SUSTAIN-6 and SELECT trials) also reduces MACE and cardiovascular mortality. Sulfonylureas and thiazolidinediones cause weight gain. DPP-4 inhibitors are weight-neutral. Oral semaglutide (Rybelsus) offers a convenient once-daily oral option.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetes — Type 2 Management','hard','mcq','A 62-year-old with Type 2 DM and prior myocardial infarction is on metformin with HbA1c 65 mmol/mol. Which add-on therapy has the BEST evidence for reducing cardiovascular mortality?','["A. SGLT-2 inhibitors (e.g. empagliflozin) or GLP-1 receptor agonists (e.g. liraglutide)","B. Sulfonylureas (e.g. glibenclamide)","C. DPP-4 inhibitors (e.g. sitagliptin -- cardiovascular neutral)","D. Alpha-glucosidase inhibitors (e.g. acarbose)"]','A','In T2DM with established atherosclerotic CVD, SGLT-2 inhibitors and GLP-1 RAs are guideline-preferred second agents: empagliflozin (EMPA-REG OUTCOME) reduced CV death by 38% and HF hospitalisation by 35%; liraglutide (LEADER) reduced CV death by 22%; semaglutide (SUSTAIN-6) reduced MACE. Both classes also provide renoprotection. Sulfonylureas have no proven CV mortality benefit; DPP-4 inhibitors are CV-neutral; saxagliptin (DPP-4i) may increase HF hospitalisation risk.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetes — Type 2 Management','medium','mcq','What is the PRIMARY mechanism of action of metformin in Type 2 diabetes mellitus?','["A. Stimulates pancreatic beta-cell insulin secretion (insulin secretagogue)","B. Reduces hepatic glucose production by activating AMPK (AMP-activated protein kinase)","C. Inhibits renal glucose reabsorption via SGLT-2 in the proximal tubule","D. Enhances GLP-1 release from gut L-cells"]','B','Metformins primary mechanism: activation of hepatic AMP-activated protein kinase (AMPK), which inhibits gluconeogenic enzymes (PEPCK, G6Pase), reducing fasting hepatic glucose output. Secondary effects: improved peripheral insulin sensitivity, modest reduction in intestinal glucose absorption, possible effects on gut microbiome and bile acid metabolism. Because metformin does not stimulate insulin secretion, hypoglycaemia as monotherapy is rare.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetes — Type 2 Management','medium','mcq','A patient with Type 2 DM on metformin 1 g BD has an eGFR of 28 mL/min/1.73m2. What is the MOST appropriate action?','["A. Continue metformin at the same dose -- safe above eGFR 15","B. Reduce to 500 mg once daily and monitor closely","C. Stop metformin -- eGFR <30 mL/min is a contraindication due to lactic acidosis risk","D. Increase dose to improve glycaemia before kidneys worsen further"]','C','Metformin is contraindicated when eGFR <30 mL/min due to accumulation and risk of lactic acidosis. MHRA/BNF guidance: eGFR 45-59: continue with monitoring; eGFR 30-44: reduce dose and review 3-6 monthly; eGFR <30: STOP metformin. Metformin should also be withheld 48 hours before contrast procedures in patients with eGFR <60 mL/min. Alternative agents (gliclazide with dose reduction, DPP-4 inhibitors adjusted for renal function) are used when metformin is contraindicated.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetes — Type 2 Management','hard','mcq','A frail 74-year-old woman with Type 2 DM, heart failure, and CKD stage 3b has HbA1c 78 mmol/mol. What HbA1c target is MOST appropriate?','["A. <48 mmol/mol (6.5%) -- maximise microvascular protection","B. <53 mmol/mol (7.0%) -- standard adult target regardless of age","C. <64 mmol/mol (8.0%) -- intermediate target","D. <=69-75 mmol/mol (<=8.5-9.0%) -- relaxed target appropriate for frail elderly"]','D','Frail elderly patients with multiple comorbidities warrant relaxed glycaemic targets: the ACCORD trial showed intensive control increased mortality in high-risk patients. Benefits of tight control (microvascular protection) take 5-10 years to manifest. Target HbA1c <=69-75 mmol/mol (<=8.5-9%) avoids hypoglycaemia risk (falls, fractures, cardiovascular events). The NICE NG28 guidance recommends individualised targets accounting for life expectancy, comorbidities, and hypoglycaemia risk.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetes — Type 2 Management','easy','mcq','What blood pressure target is recommended in patients with Type 2 DM and diabetic nephropathy?','["A. <130/80 mmHg","B. <150/90 mmHg","C. <160/100 mmHg","D. <120/70 mmHg"]','A','Patients with T2DM and nephropathy (microalbuminuria or proteinuria) require BP <130/80 mmHg. ACE inhibitors (lisinopril, ramipril) or ARBs (losartan, valsartan) are first-choice antihypertensives -- they reduce intraglomerular pressure, decrease proteinuria by 30-40%, and slow GFR decline independently of BP lowering. UACR (urine albumin:creatinine ratio) should be monitored at diagnosis and annually. Combination ACEi + ARB is not recommended (increased risk of hyperkalaemia and AKI).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetes — Type 2 Management','medium','mcq','A 50-year-old man initiated on glibenclamide for Type 2 DM must be counselled about which MOST IMPORTANT adverse effect?','["A. Lactic acidosis (as with metformin)","B. Hypoglycaemia -- especially prolonged episodes in the elderly or those skipping meals","C. Diabetic ketoacidosis from beta-cell overstimulation","D. Urinary tract infections and genital mycotic infections"]','B','Sulfonylureas (glibenclamide, glipizide, gliclazide) stimulate insulin secretion independent of blood glucose, risking hypoglycaemia -- especially in elderly patients (impaired counter-regulation), those with renal impairment (drug accumulation), or those who skip meals. Glibenclamide has the highest risk due to long half-life and active renally-excreted metabolites. Shorter-acting sulfonylureas (gliclazide MR) are preferred in the elderly. Patients must be counselled on hypoglycaemia recognition and management (Rule of 15).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetic Ketoacidosis','easy','mcq','Which biochemical triad is DIAGNOSTIC of diabetic ketoacidosis (DKA)?','["A. Glucose >30 mmol/L, osmolality >320 mOsm/kg, absent significant ketones","B. Glucose >11 mmol/L, pH <7.3 (or bicarbonate <15 mmol/L), and significant ketonaemia (>=3 mmol/L) or ketonuria","C. Glucose >7 mmol/L, pH <7.35, lactate >4 mmol/L","D. Glucose >15 mmol/L, pH <7.1, HbA1c >75 mmol/mol"]','B','DKA diagnostic triad: (1) Hyperglycaemia >11 mmol/L (euglycaemic DKA can occur with SGLT-2 inhibitors); (2) Metabolic acidosis: pH <7.3 and/or bicarbonate <15 mmol/L; (3) Ketonaemia >=3 mmol/L or significant ketonuria (2+ on dipstick). DKA results from absolute/relative insulin deficiency with excess counter-regulatory hormones, promoting lipolysis and ketogenesis (acetoacetate, beta-hydroxybutyrate).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetic Ketoacidosis','easy','mcq','What is the FIRST-LINE IV fluid for resuscitation in diabetic ketoacidosis?','["A. 5% dextrose -- to provide energy substrate","B. 0.9% sodium chloride (normal saline)","C. 0.45% hypotonic sodium chloride","D. Colloid (Gelofusine or Voluven)"]','B','0.9% NaCl is the recommended first-line fluid for DKA. Standard JBDS UK protocol: 1 L over 1 hour initially (faster if haemodynamically shocked), then subsequent litres based on clinical assessment. 5% dextrose is added only when glucose falls below 14 mmol/L, to allow continued insulin infusion without causing hypoglycaemia. This is essential as insulin must continue to clear ketones even after glucose normalises.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetic Ketoacidosis','medium','mcq','What is the standard fixed-rate intravenous insulin infusion (FRIII) rate used in DKA management?','["A. 0.05 units/kg/hr","B. 0.15 units/kg/hr","C. 0.1 units/kg/hr of human soluble insulin (e.g. Actrapid)","D. 2 units/hr regardless of body weight"]','C','FRIII: 0.1 units/kg/hr of human soluble insulin (e.g. Actrapid) -- weight-based to account for variable insulin sensitivity. Started once IV fluid resuscitation is underway. If on long-acting subcutaneous insulin (e.g. glargine), CONTINUE it alongside the FRIII. The rate is NOT titrated based on glucose levels; DKA resolution is determined by pH, bicarbonate, and ketone levels -- not glucose alone.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetic Ketoacidosis','medium','mcq','In DKA management, insulin infusion must continue until which DKA RESOLUTION criteria are met?','["A. Blood glucose falls below 14 mmol/L","B. Blood pressure and heart rate normalise","C. Patient is able to eat and drink normally","D. pH >7.3, bicarbonate >18 mmol/L, AND blood ketones <0.6 mmol/L"]','D','DKA resolution criteria (JBDS protocol): blood ketones <0.6 mmol/L, venous pH >7.3, bicarbonate >18 mmol/L. ALL three must be met before stopping insulin infusion. Glucose normalises well before ketoacidosis resolves -- 5% dextrose is added when glucose falls <14 mmol/L to allow continued insulin administration. Premature insulin cessation when only glucose normalises leads to rebound ketosis.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetic Ketoacidosis','hard','mcq','In DKA, why must potassium be checked and corrected BEFORE insulin is started if K+ <3.5 mmol/L?','["A. Insulin drives K+ into cells, risking fatal hypokalaemia and cardiac arrhythmias if pre-existing K+ is already low","B. Insulin raises serum potassium causing dangerous hyperkalaemia","C. Low potassium inhibits insulin receptor signalling","D. Low potassium indicates the DKA diagnosis is incorrect"]','A','DKA causes total body K+ depletion (urinary losses) despite often-normal or elevated serum K+ (acidosis shifts K+ extracellularly). Insulin drives K+ back into cells, rapidly lowering serum K+. Protocol: K+ <3.5 mmol/L -- WITHHOLD insulin and replace K+ with IV KCl until K+ >=3.5; K+ 3.5-5.5 -- start insulin AND add KCl 40 mmol per litre of fluid; K+ >5.5 -- start insulin WITHOUT KCl, recheck K+ in 1 hour. Monitor K+ every 1-2 hours in DKA.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetic Ketoacidosis','hard','mcq','In DKA, when is IV sodium bicarbonate considered according to current JBDS guidelines?','["A. Routinely for all DKA patients with pH <7.3","B. Only if pH <6.9 after initial resuscitation and only after senior/specialist review","C. Bicarbonate must never be given in DKA","D. Immediately for all severe DKA patients with pH <7.1"]','B','IV sodium bicarbonate in DKA is controversial and potentially harmful: paradoxical intracellular/CNS acidosis, worsening hypokalaemia, shift of oxygen-haemoglobin dissociation curve (reduced O2 delivery). JBDS guidance: consider bicarbonate ONLY if pH <6.9 after initial resuscitation, given as 100 mmol over 1 hour with additional potassium, and ONLY after senior/specialist discussion. Routine use is not recommended. Fluid resuscitation and insulin remain the cornerstone of treatment.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetic Ketoacidosis','medium','mcq','A 32-year-old woman presents in DKA with GCS 12. Which complication of DKA fluid management must be carefully considered?','["A. Pulmonary oedema from excessive fluids in all DKA patients","B. Cerebral oedema -- more common in young/paediatric patients; avoid overly rapid fluid or osmolality correction","C. Acute liver failure from hyperosmolality correction","D. Rebound hyperglycaemia from too-rapid glucose correction"]','B','Cerebral oedema is a rare but potentially fatal complication of DKA, more common in children and young adults (under 25). Risk factors: aggressive hypotonic fluid replacement, too-rapid osmolality correction, bicarbonate therapy. Clinical features: headache, deteriorating consciousness, pupillary changes. Management: mannitol 0.5-1 g/kg IV or hypertonic (3%) saline. Prevention: follow standard JBDS fluid protocols and avoid excessive free water.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetic Ketoacidosis','easy','mcq','Which of the following is the MOST COMMON precipitating cause of DKA?','["A. Excessive carbohydrate intake","B. Missed insulin doses or concurrent infection (e.g. UTI, pneumonia)","C. Hypoglycaemia triggering counter-regulatory response","D. Hypothyroidism"]','B','DKA precipitants: (1) Missed/insufficient insulin -- most common in known T1DM; (2) Infection -- UTI, pneumonia, cellulitis (increases counter-regulatory hormones and insulin resistance); (3) New-onset T1DM (25-30% of DKA cases are first presentations); (4) Other stressors: MI, stroke, pancreatitis, surgery, trauma; (5) Drugs: corticosteroids, SGLT-2 inhibitors (euglycaemic DKA). Identifying and treating the precipitant is essential for management and relapse prevention.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetic Ketoacidosis','medium','mcq','How is DKA severity CLASSIFIED according to standard protocols?','["A. Mild: pH 7.25-7.30; Moderate: pH 7.00-7.24; Severe: pH <7.00","B. Mild: glucose <20; Moderate: 20-30; Severe: >30 mmol/L","C. Mild: ketones 1-2; Moderate: 2-3; Severe: >3 mmol/L","D. Classified by HbA1c level at admission"]','A','DKA severity (JBDS/UK guidelines) by venous pH: Mild: pH 7.25-7.30 (bicarbonate 15-18 mmol/L); Moderate: pH 7.00-7.24 (bicarbonate 10-14 mmol/L); Severe: pH <7.00 (bicarbonate <10 mmol/L). Severity guides monitoring frequency, escalation to HDU/ICU, and indicates need for senior review. GCS and clinical features also determine management intensity. Severe DKA requires HDU/ICU-level care.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Diabetic Ketoacidosis','medium','mcq','When is it safe to transition a DKA patient from IV insulin infusion to subcutaneous insulin?','["A. When glucose falls below 14 mmol/L -- no need to wait further","B. When DKA resolution criteria are met AND the patient is alert and able to eat and drink","C. Automatically after 6 hours of IV insulin regardless of biochemistry","D. When blood pressure and heart rate normalise to baseline"]','B','Transition from IV to subcutaneous insulin requires: (1) DKA resolution criteria met (pH >7.3, bicarbonate >18 mmol/L, ketones <0.6 mmol/L); AND (2) Patient is alert, able to eat and drink normally. The first subcutaneous insulin dose should be given 30-60 minutes BEFORE stopping the IV infusion to prevent a gap in insulin coverage (risk of rebound ketosis). For new-onset T1DM, a structured insulin regimen must be prescribed with diabetes specialist nurse education.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Hyperosmolar Hyperglycaemic State & Hypoglycaemia','easy','mcq','Which glucose and osmolality values define Hyperosmolar Hyperglycaemic State (HHS)?','["A. Glucose >11 mmol/L and osmolality >280 mOsm/kg","B. Glucose >30 mmol/L and effective osmolality >320 mOsm/kg with absent/minimal ketoacidosis","C. Glucose >20 mmol/L and osmolality >300 mOsm/kg","D. Glucose >15 mmol/L and osmolality >310 mOsm/kg"]','B','HHS: (1) Blood glucose >30 mmol/L (often 40-80 mmol/L); (2) Effective plasma osmolality >320 mOsm/kg (= 2x[Na] + [glucose]); (3) Profound dehydration (fluid deficit 8-10 L); (4) Absent/minimal ketoacidosis (pH >7.3, bicarbonate >15 mmol/L, ketones <3 mmol/L -- residual insulin prevents lipolysis). HHS typically occurs in elderly Type 2 DM patients, often precipitated by infection, MI, stroke, or diuretics. Mortality is higher than DKA (~15-20%).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Hyperosmolar Hyperglycaemic State & Hypoglycaemia','medium','mcq','What BEST distinguishes HHS from DKA in a hyperglycaemic patient?','["A. HHS has profound hyperglycaemia (>30 mmol/L), hyperosmolality, and absent/minimal ketoacidosis","B. DKA has higher blood glucose levels than HHS","C. HHS occurs exclusively in young Type 1 diabetics","D. DKA never causes altered consciousness"]','A','HHS vs DKA: HHS -- extreme hyperglycaemia (>30, often >50 mmol/L), severe hyperosmolality (>320 mOsm/kg), minimal ketosis, elderly Type 2 DM patients, gradual onset over days, mortality ~15-20%. DKA -- moderate hyperglycaemia (>11 mmol/L), significant ketonaemia and acidaemia (pH <7.3), predominantly Type 1 DM, acute onset over hours, mortality <2% with treatment. Neurological features are more prominent in HHS due to extreme osmolality.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Hyperosmolar Hyperglycaemic State & Hypoglycaemia','medium','mcq','What is the MOST appropriate initial fluid resuscitation in HHS?','["A. 0.45% hypotonic saline -- 2 L over 1 hour to correct free water deficit","B. 5% dextrose -- to replace free water most effectively","C. 0.9% sodium chloride -- 1 L over 1 hour, then reassess fluid status","D. Albumin colloid -- for better oncotic pressure in elderly patients"]','C','HHS fluid management: (1) 0.9% NaCl initially -- restores circulating volume and promotes renal glucose excretion. Total fluid deficit is 8-10 L; replace gradually over 24-48 hours. (2) If plasma sodium is not falling and osmolality remains high, consider 0.45% NaCl. (3) Osmolality should fall no faster than 3-8 mOsm/kg/hr; glucose no faster than 5 mmol/L/hr to avoid cerebral oedema. (4) Low-dose insulin (0.05 units/kg/hr) only after initial fluids if glucose not falling.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Hyperosmolar Hyperglycaemic State & Hypoglycaemia','easy','mcq','A conscious patient with Type 2 DM on glibenclamide has a capillary glucose of 2.8 mmol/L and is alert and able to swallow. The FIRST-LINE treatment is:','["A. IV dextrose 50% -- 50 mL stat bolus","B. Glucagon 1 mg intramuscular injection","C. Stop glibenclamide and observe for 4 hours","D. 15-20 g fast-acting oral carbohydrate (e.g. glucose tablets, Lucozade, fruit juice)"]','D','"Rule of 15" for mild/moderate hypoglycaemia in conscious patients able to swallow: 15-20 g fast-acting oral carbohydrate -- 4-5 glucose tablets (4 g each), 200 mL orange juice, or 150 mL Lucozade. Recheck glucose after 15 minutes; repeat if still <4 mmol/L. Once glucose >4 mmol/L, give a longer-acting starchy snack. IV dextrose and IM glucagon are reserved for unconscious or unable-to-swallow patients. Glibenclamide-induced hypoglycaemia can be prolonged -- monitor for recurrence.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Hyperosmolar Hyperglycaemic State & Hypoglycaemia','hard','mcq','An unconscious patient with Type 1 DM has capillary glucose of 1.9 mmol/L. No IV access is available. What is the MOST appropriate immediate treatment?','["A. Oral glucose gel applied to the gums","B. Nasogastric tube glucose administration","C. Await IV access before administering any treatment","D. Glucagon 1 mg intramuscular (or subcutaneous) injection"]','D','Glucagon 1 mg IM or SC is the treatment for severe hypoglycaemia when the patient is unconscious and IV access is unavailable. Glucagon stimulates hepatic glycogenolysis, raising blood glucose in 10-15 minutes. Limitations: may be less effective in glycogen-depleted patients (starvation, alcoholism, adrenal insufficiency). Oral glucose is contraindicated in unconscious patients (aspiration risk). Once IV access is secured, give IV dextrose (75-100 mL of 20% dextrose or 150-200 mL of 10% dextrose).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Hyperosmolar Hyperglycaemic State & Hypoglycaemia','medium','mcq','A 68-year-old with Type 2 DM on insulin is confused with glucose 1.4 mmol/L. IV access is obtained. What is the CORRECT IV treatment?','["A. IV 50% dextrose -- 50 mL bolus (traditional approach)","B. IV 10% dextrose 150-200 mL over 15 minutes (or IV 20% dextrose 75-100 mL)","C. IV 5% dextrose -- 1 litre over 1 hour","D. IV normal saline -- to restore circulating volume first"]','B','For severe hypoglycaemia with IV access: IV 10% dextrose 150-200 mL over 15 minutes, or IV 20% dextrose 75-100 mL over 15 minutes. These are now preferred over 50% dextrose, which is highly hypertonic, irritant to veins, and associated with tissue necrosis if extravasated. Recheck glucose every 15 minutes; repeat dextrose if glucose remains <4 mmol/L. Once conscious and able to swallow, give a starchy snack. A glucose infusion may be needed to prevent recurrence with long-acting agents.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Hyperosmolar Hyperglycaemic State & Hypoglycaemia','hard','mcq','Which patient population is at HIGHEST risk for hypoglycaemia unawareness (loss of warning symptoms)?','["A. Newly diagnosed Type 2 DM patients on metformin monotherapy","B. Patients with long-standing Type 1 DM who have experienced frequent hypoglycaemic episodes","C. Obese patients on pioglitazone monotherapy","D. Patients on DPP-4 inhibitors alone"]','B','Hypoglycaemia unawareness occurs in long-standing Type 1 DM after repeated hypoglycaemic episodes. Mechanism: attenuated counter-regulatory response (reduced glucagon and adrenaline secretion), loss of autonomic warning symptoms (sweating, tremor, palpitations). Patients experience neuroglycopenic symptoms (confusion, seizures, coma) without preceding warning. Management: relax glucose targets, structured education (DAFNE programme), continuous glucose monitoring (CGM) with real-time low glucose alerts.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Hyperosmolar Hyperglycaemic State & Hypoglycaemia','medium','mcq','What is the formula for EFFECTIVE (tonicity) plasma osmolality used in HHS assessment?','["A. 2x(Na + K) + glucose + urea -- total osmolality","B. 2xNa + glucose + urea (all in mmol/L)","C. 2xNa + glucose (mmol/L) -- urea excluded as it freely crosses cell membranes","D. Na + K + glucose + urea"]','C','Effective osmolality (tonicity) = 2x[Na] + [glucose] (both in mmol/L). Urea is excluded because it equilibrates freely across cell membranes and does NOT contribute to effective osmotic pressure or transcellular water movement. Total osmolality includes urea but effective osmolality (the clinically relevant parameter for HHS) excludes it. Normal effective osmolality: 275-295 mOsm/kg. In HHS: >320 mOsm/kg drives severe cellular dehydration.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Hyperosmolar Hyperglycaemic State & Hypoglycaemia','easy','mcq','Which conditions cause FALSELY LOW HbA1c, leading to underestimation of glycaemic control?','["A. Chronic kidney disease","B. Obesity","C. Haemolytic anaemia, haemoglobinopathies (e.g. sickle cell disease), or recent blood transfusion","D. Hypothyroidism"]','C','HbA1c reflects average glucose over the red cell lifespan (~120 days). Conditions shortening red cell survival cause falsely LOW HbA1c: haemolytic anaemia, haemoglobinopathies (HbS, HbC, HbE), recent transfusion (new RBCs not yet glycated), iron deficiency anaemia. Splenectomy can cause falsely HIGH HbA1c (prolonged RBC survival). In these patients, use fructosamine or continuous glucose monitoring instead of HbA1c for monitoring glycaemic control.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Hyperosmolar Hyperglycaemic State & Hypoglycaemia','hard','mcq','A 75-year-old with Type 2 DM presents with 5-day history of polyuria and progressive confusion. Glucose is 58 mmol/L, Na+ 152, effective osmolality 368 mOsm/kg, pH 7.36, ketones 0.8 mmol/L. What is the DIAGNOSIS and most critical initial intervention?','["A. DKA -- start fixed-rate insulin infusion 0.1 units/kg/hr immediately","B. HHS -- aggressive IV 0.9% NaCl resuscitation is the MOST critical first intervention","C. Lactic acidosis -- IV sodium bicarbonate immediately","D. SIADH -- fluid restrict to 1 L/day"]','B','This is HHS: glucose >30 mmol/L (58 mmol/L), osmolality >320 (368 mOsm/kg), no significant ketoacidosis (pH normal, ketones <3 mmol/L). Most critical first intervention: aggressive IV 0.9% NaCl rehydration -- the fluid deficit is enormous (8-10 L). Fluid alone will lower glucose and osmolality significantly. Low-dose insulin (0.05 units/kg/hr) is added if glucose fails to fall with fluids alone. Avoid rapid osmolality correction (risk of cerebral oedema). DVT prophylaxis should be considered (high thrombosis risk in HHS).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Thyroid Disease — Hypothyroidism Management','easy','mcq','What is the FIRST-LINE treatment for primary hypothyroidism?','["A. Liothyronine (T3) alone -- more potent than T4","B. Levothyroxine (L-T4) oral therapy -- daily dosing","C. Combined T3/T4 combination therapy for all patients","D. Propylthiouracil (PTU) -- blocks excess thyroid hormone"]','B','Levothyroxine (L-T4) is standard first-line treatment for primary hypothyroidism. Peripheral tissues convert T4 to the active T3 via deiodinases. Standard full replacement dose: 1.6 mcg/kg/day. Taken 30-60 minutes before food on an empty stomach for optimal absorption. Liothyronine (T3) has a shorter half-life and greater cardiovascular effects -- not recommended as routine monotherapy. Combined T3/T4 has no proven benefit over T4 alone in most patients.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Thyroid Disease — Hypothyroidism Management','easy','mcq','How is the adequacy of levothyroxine treatment for primary hypothyroidism MONITORED?','["A. Free T3 levels only -- T3 is the active hormone","B. TSH measured within the normal reference range (0.4-4.0 mU/L)","C. Total T4 levels -- check against the reference range","D. Symptom score assessment alone -- no blood tests needed once stable"]','B','In primary hypothyroidism, TSH is the most sensitive indicator of levothyroxine adequacy. The pituitary is exquisitely sensitive to thyroid hormone -- a TSH within the normal range (0.4-4.0 mU/L) confirms appropriate replacement. TSH should be checked 6-8 weeks after initiating or adjusting dose, and annually once stable. Free T4 may be useful in secondary hypothyroidism (pituitary disease) where TSH cannot be used as a monitor.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Thyroid Disease — Hypothyroidism Management','medium','mcq','A woman with primary hypothyroidism on levothyroxine has persistently elevated TSH despite dose increases. She takes levothyroxine simultaneously with coffee and calcium supplements. The MOST likely explanation is:','["A. She has developed secondary hypothyroidism from pituitary failure","B. Her TSH assay is unreliable -- switch to free T4 monitoring","C. Calcium carbonate and coffee significantly impair levothyroxine absorption","D. She needs T3 (liothyronine) added to achieve euthyroidism"]','C','Multiple substances impair levothyroxine absorption by up to 40%: calcium carbonate (most significant), ferrous sulphate, antacids (PPIs, H2 blockers), cholestyramine, coffee (even 1 hour after). Management: counsel patient to take levothyroxine on an empty stomach, at least 30-60 minutes before breakfast, separated from interfering substances by >=4 hours. Liquid levothyroxine or soft gel capsules have better absorption when taken with food.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Thyroid Disease — Hypothyroidism Management','medium','mcq','What is the recommended starting levothyroxine dose in a 72-year-old man with newly diagnosed hypothyroidism and known ischaemic heart disease?','["A. Full replacement dose immediately: 1.6 mcg/kg/day","B. Standard adult dose: 100 mcg once daily","C. 200 mcg/day -- to rapidly reverse hypothyroidism","D. 12.5-25 mcg/day, titrated slowly upward every 6-8 weeks"]','D','In elderly patients and those with ischaemic heart disease, levothyroxine must be started at a LOW dose (12.5-25 mcg/day) and titrated slowly (every 6-8 weeks) to avoid precipitating angina, MI, or arrhythmias. Thyroid hormone increases heart rate, contractility, and myocardial oxygen demand. Full replacement doses are appropriate for healthy young adults. Titrate guided by TSH and clinical response.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Thyroid Disease — Hypothyroidism Management','easy','mcq','Subclinical hypothyroidism is defined as:','["A. TSH elevated (4.5-10 mU/L) with normal free T4 and no or minimal symptoms","B. TSH >10 mU/L with low free T4 and overt symptoms","C. TSH <0.1 mU/L with low free T4 and symptoms","D. Normal TSH with low free T4 (consistent with secondary hypothyroidism)"]','A','Subclinical hypothyroidism = elevated TSH (typically 4.5-10 mU/L) + NORMAL free T4 + absent or minimal symptoms. Treatment decisions depend on: TSH level (>10 mU/L -- most guidelines recommend treatment); symptoms; anti-TPO antibody positivity (increased progression risk); age; pregnancy (treat even mild elevation). Asymptomatic elderly patients with TSH 4.5-10 mU/L may be monitored rather than treated immediately.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Thyroid Disease — Hypothyroidism Management','hard','mcq','A 30-year-old pregnant woman (12 weeks gestation) has TSH 6.8 mU/L and positive anti-TPO antibodies. What is the CORRECT management?','["A. Reassure -- some TSH elevation is expected and normal in pregnancy","B. Start levothyroxine immediately to protect fetal neurodevelopment","C. Repeat TSH at 20 weeks gestation before deciding on treatment","D. Start T3 (liothyronine) -- only T3 crosses the placenta effectively"]','B','In pregnancy, even subclinical hypothyroidism requires treatment with levothyroxine. The fetus is entirely dependent on maternal T4 for brain development during the first trimester (fetal thyroid not functional until 10-12 weeks). TSH targets in pregnancy: first trimester <2.5 mU/L; second and third trimester <3.0 mU/L. Anti-TPO antibodies indicate high risk of progression and obstetric complications. Levothyroxine dose typically needs to be increased by 25-50% from pre-pregnancy levels.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Thyroid Disease — Hypothyroidism Management','hard','mcq','A patient with severe long-standing hypothyroidism presents with GCS 10, hypothermia (33.5 degrees C), bradycardia (42 bpm), and hyponatraemia. This is myxoedema coma. The EMERGENCY treatment is:','["A. Oral levothyroxine at standard doses -- rapid IV replacement is dangerous","B. IV levothyroxine 200-500 mcg stat plus or minus IV liothyronine, IV hydrocortisone 100 mg, and ICU admission","C. External cardiac pacing for bradycardia before thyroid hormone replacement","D. Anti-thyroid drugs to reduce autoimmune destruction of the thyroid"]','B','Myxoedema coma: mortality 40-60% without treatment. Management: (1) IV levothyroxine 200-500 mcg loading dose, then 50-100 mcg/day IV; (2) IV liothyronine (T3) 5-20 mcg q8h can be added for faster onset; (3) IV hydrocortisone 100 mg BEFORE thyroid hormone -- to prevent adrenal crisis (coexistent adrenal insufficiency is common in this setting); (4) Passive rewarming; (5) IV fluids; (6) Treat precipitant; (7) ICU admission.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Thyroid Disease — Hypothyroidism Management','medium','mcq','Which antibody is MOST commonly elevated in Hashimoto thyroiditis causing primary hypothyroidism?','["A. Anti-thyroglobulin antibodies -- found in 60% of cases","B. Anti-TSH receptor stimulating antibodies (TRAb/TSI) -- diagnostic of Graves disease","C. Anti-thyroid peroxidase (anti-TPO) antibodies -- found in >90% of Hashimoto thyroiditis","D. Anti-nuclear antibodies (ANA) -- diagnostic of systemic lupus"]','C','Hashimoto thyroiditis is characterised by anti-TPO antibodies (present in >90% of patients) -- the most sensitive marker. Anti-thyroglobulin antibodies are also elevated but less specific. Anti-TPO antibodies indicate autoimmune destruction of thyroid follicular cells (T-cell mediated + complement activation). TSH receptor stimulating antibodies (TRAb/TSI) are the hallmark of Graves disease. Anti-TPO positivity in subclinical hypothyroidism predicts ~4% annual risk of progression to overt hypothyroidism.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Thyroid Disease — Hypothyroidism Management','medium','mcq','A patient on levothyroxine has a suppressed TSH (0.05 mU/L) and complains of palpitations and heat intolerance. The MOST appropriate management is:','["A. Add a beta-blocker -- symptoms are unrelated to levothyroxine dose","B. Reduce the levothyroxine dose and recheck TSH in 6-8 weeks","C. Stop levothyroxine completely and restart in 4 weeks","D. Add carbimazole to block excess thyroid hormone"]','B','Suppressed TSH on levothyroxine indicates over-replacement (iatrogenic thyrotoxicosis). This significantly increases risk of atrial fibrillation and osteoporosis. Management: reduce levothyroxine dose by 25 mcg and recheck TSH in 6-8 weeks. Target TSH 0.4-4.0 mU/L. Abrupt cessation risks rebound hypothyroidism. Carbimazole is inappropriate for iatrogenic hyperthyroidism. Subclinical iatrogenic hyperthyroidism in elderly/osteoporotic patients also warrants dose reduction.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Thyroid Disease — Hypothyroidism Management','hard','mcq','A patient on levothyroxine 125 mcg/day starts taking rifampicin for tuberculosis treatment. What adjustment is required for levothyroxine?','["A. No change needed -- rifampicin does not affect thyroid hormone levels","B. Reduce levothyroxine dose -- rifampicin increases T4 levels","C. Increase levothyroxine dose -- rifampicin induces CYP450 enzymes increasing T4 metabolism","D. Switch to T3 (liothyronine) which is not affected by enzyme inducers"]','C','Rifampicin is a potent CYP450 enzyme inducer, accelerating levothyroxine metabolism and lowering T4 levels. Other enzyme inducers with similar effects: phenytoin, carbamazepine, phenobarbitone. Result: previously well-controlled hypothyroidism becomes under-treated. Management: increase levothyroxine dose and monitor TSH every 4-6 weeks. Other drug interactions: antacids/PPIs and calcium impair absorption; amiodarone inhibits T4-to-T3 conversion and may cause hypo- or hyperthyroidism.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Thyroid Disease — Hyperthyroidism & Thyroid Storm Management','easy','mcq','What is the MOST COMMON cause of hyperthyroidism worldwide?','["A. Toxic multinodular goitre (Plummer disease)","B. Subacute (de Quervain) thyroiditis -- transient thyrotoxicosis","C. Graves disease -- autoimmune TSH-receptor stimulation","D. Factitious hyperthyroidism from levothyroxine excess"]','C','Graves disease accounts for 60-80% of hyperthyroidism. It is caused by TSH receptor stimulating antibodies (TRAb/TSI) that constitutively activate the TSH receptor, driving unregulated thyroid hormone production. It is more common in women (F:M = 7-10:1) and young adults. Features unique to Graves: ophthalmopathy (exophthalmos, lid retraction, ophthalmoplegia), pretibial myxoedema, and thyroid acropachy.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Thyroid Disease — Hyperthyroidism & Thyroid Storm Management','easy','mcq','Which anti-thyroid drug is PREFERRED in the first trimester of pregnancy for Graves hyperthyroidism?','["A. Carbimazole -- first choice in all trimesters of pregnancy","B. Propylthiouracil (PTU) -- preferred in first trimester due to lower teratogenicity risk","C. Radioiodine (I-131) -- safe in first trimester only","D. Total thyroidectomy in first trimester for definitive treatment"]','B','PTU is preferred in the first trimester because carbimazole/methimazole is associated with teratogenicity: aplasia cutis congenita, choanal atresia, oesophageal atresia ("methimazole embryopathy"). PTU has lower teratogenic risk in early pregnancy. From the second trimester onward, carbimazole/methimazole can be used (PTU has rare but serious hepatotoxicity). Radioiodine is absolutely contraindicated throughout pregnancy and breastfeeding (destroys the fetal thyroid).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Thyroid Disease — Hyperthyroidism & Thyroid Storm Management','medium','mcq','Which scoring system is used to assess the likelihood of thyroid storm?','["A. SOFA score -- used in sepsis assessment","B. Modified Early Warning Score (MEWS)","C. Burch-Wartofsky Point Scale (BWPS)","D. Glasgow Coma Scale (GCS) alone"]','C','The Burch-Wartofsky Point Scale (BWPS) diagnoses thyroid storm by scoring: (1) Thermoregulatory dysfunction (temperature); (2) Cardiovascular (heart rate, AF, heart failure); (3) CNS dysfunction (agitation, delirium, psychosis, coma, seizures); (4) GI/hepatic dysfunction (nausea, vomiting, jaundice); (5) Precipitating event. Score >=45 = thyroid storm; 25-44 = impending storm; <25 = unlikely. A Japanese variant scoring system is also used.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Thyroid Disease — Hyperthyroidism & Thyroid Storm Management','medium','mcq','In thyroid storm, which is the CORRECT sequence for administering antithyroid drugs and Lugol iodine?','["A. Lugol iodine first (blocks release), then antithyroid drug (blocks synthesis)","B. Both given simultaneously for maximal synergistic effect","C. Antithyroid drug (PTU/carbimazole) FIRST, then Lugol iodine at least 1 hour LATER","D. Lugol iodine alone is sufficient -- antithyroid drugs are not needed"]','C','Critical sequencing in thyroid storm: Give PTU (500-1000 mg loading) or carbimazole (60-80 mg) FIRST to block thyroid hormone SYNTHESIS -- then give Lugol iodine >=1 hour later to block thyroid hormone RELEASE (Wolff-Chaikoff effect). If iodine is given first, it can transiently increase hormone synthesis (Jod-Basedow), worsening the crisis. Complete thyroid storm treatment: antithyroid drug + iodine (>=1h later) + propranolol + IV hydrocortisone 100 mg q8h + treat precipitant + supportive care.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Thyroid Disease — Hyperthyroidism & Thyroid Storm Management','easy','mcq','Which drug class provides RAPID control of tachycardia and adrenergic symptoms in Graves hyperthyroidism while awaiting effect of antithyroid drugs?','["A. Beta-adrenergic blockers (e.g. propranolol 40 mg TDS)","B. Carbimazole alone -- takes 4-8 weeks to achieve euthyroidism","C. Radioiodine I-131 -- works within days","D. Levothyroxine -- to normalise pituitary feedback"]','A','Beta-blockers (propranolol, atenolol) rapidly control adrenergic symptoms of hyperthyroidism: tachycardia, palpitations, tremor, heat intolerance, anxiety. Propranolol at high doses (>160 mg/day) also inhibits peripheral T4-to-T3 conversion (type 1 deiodinase). Antithyroid drugs take 4-8 weeks to achieve euthyroidism by blocking synthesis. Beta-blockers are essential in thyroid storm alongside antithyroid drugs, iodine, and steroids.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Thyroid Disease — Hyperthyroidism & Thyroid Storm Management','hard','mcq','A 35-year-old woman with Graves disease is treated with radioiodine (I-131). What is the MOST COMMON long-term outcome?','["A. Permanent cure -- all patients achieve permanent euthyroidism","B. Most patients eventually develop hypothyroidism, requiring lifelong levothyroxine","C. Radioiodine always causes worsening Graves ophthalmopathy requiring immediate systemic steroids","D. TRAb antibodies are eliminated by radioiodine treatment"]','B','Radioiodine (I-131) is effective for Graves hyperthyroidism but the most common long-term outcome is hypothyroidism -- occurring in 50-80% at 1 year, up to 90% by 10 years. All patients must be counselled about likely lifelong levothyroxine requirement. Contraindications: pregnancy, breastfeeding, severe active Graves ophthalmopathy (can worsen eye disease -- prophylactic oral steroids given if mild-moderate eye disease is present). Radioiodine is not associated with increased cancer risk in adults.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Thyroid Disease — Hyperthyroidism & Thyroid Storm Management','hard','mcq','Which investigation MOST RELIABLY confirms Graves disease as the cause of hyperthyroidism?','["A. Thyroid ultrasound with Doppler showing hypervascular gland","B. TSH measurement alone -- suppressed TSH confirms Graves disease","C. Anti-TPO antibodies alone (elevated in both Graves and Hashimoto)","D. TRAb (TSH receptor antibody) or TSI (thyroid stimulating immunoglobulin) assay"]','D','TRAb (TSH receptor antibodies) or TSI are present in >95% of Graves disease patients, confirming the autoimmune aetiology. They distinguish Graves from toxic nodular goitre (no TRAb) or thyroiditis (no TRAb). TRAb titres correlate with disease activity and risk of neonatal hyperthyroidism (TRAb crosses placenta). Declining TRAb predicts remission on antithyroid drugs. Anti-TPO antibodies are elevated in both Graves and Hashimoto -- not specific for Graves.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Thyroid Disease — Hyperthyroidism & Thyroid Storm Management','medium','mcq','A patient on carbimazole for Graves disease presents with sore throat and fever (38.5 degrees C). The MOST important immediate action is:','["A. Reassure -- sore throat is a common but minor side effect of carbimazole","B. Reduce carbimazole dose and add vitamin C supplement","C. Stop carbimazole immediately and obtain urgent FBC to check for agranulocytosis","D. Start amoxicillin for presumed streptococcal pharyngitis without checking FBC"]','C','Agranulocytosis (neutrophils <0.5x10^9/L) is the most serious adverse effect of carbimazole/PTU, occurring in ~0.3% of patients, typically within the first 3 months. Presentation: fever, sore throat, mouth ulcers. Management: STOP carbimazole IMMEDIATELY (before FBC result), then obtain urgent FBC. If agranulocytosis confirmed: hospital admission, G-CSF, haematology review. All patients must be counselled at initiation to stop medication and seek urgent blood tests if they develop fever or sore throat.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Thyroid Disease — Hyperthyroidism & Thyroid Storm Management','medium','mcq','What is the mechanism of action of propylthiouracil (PTU) in treating hyperthyroidism?','["A. Inhibits thyroid peroxidase (TPO) AND inhibits peripheral T4-to-T3 conversion (5-prime deiodinase)","B. Inhibits radioactive iodine uptake by the sodium-iodide symporter (NIS)","C. Destroys thyroid follicular cells by triggering complement-mediated lysis","D. Stimulates thyroid hormone binding globulin to reduce free T4 availability"]','A','PTU has two mechanisms: (1) Inhibits thyroid peroxidase (TPO), preventing iodination of tyrosine residues in thyroglobulin (blocking T3/T4 synthesis); (2) Inhibits type 1 iodothyronine 5-prime deiodinase, reducing peripheral conversion of T4 to the more potent T3. The second mechanism makes PTU superior to carbimazole in thyroid storm (where rapid T3 reduction is critical). Carbimazole (converted to methimazole) only inhibits TPO -- it does not block T4-to-T3 conversion.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Thyroid Disease — Hyperthyroidism & Thyroid Storm Management','hard','mcq','In addition to controlling heart rate, high-dose propranolol (>160 mg/day) in thyroid storm has which additional benefit?','["A. It stimulates TSH secretion to restore pituitary-thyroid feedback loop","B. It inhibits peripheral conversion of T4 to the more active T3","C. It blocks Lugol iodine from entering thyroid follicular cells","D. It reduces TRAb (TSH receptor antibody) titres directly"]','B','High-dose propranolol inhibits type 1 deiodinase (5-prime deiodinase), reducing peripheral T4-to-T3 conversion -- complementing PTUs same action. In thyroid storm, propranolol 60-120 mg orally every 4-6 hours (or IV 0.5-1 mg slowly under cardiac monitoring) is used. It controls tachycardia, AF, tremor, anxiety, and reduces the hyperadrenergic state. This dual anti-T3 effect (propranolol + PTU) is one reason PTU is preferred over carbimazole specifically in thyroid storm.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Cushing''s Syndrome — Diagnosis & Management','easy','mcq','Which is the STANDARD SCREENING TEST for Cushing syndrome?','["A. Overnight 1 mg dexamethasone suppression test (DST) -- cortisol should suppress to <50 nmol/L","B. Random serum cortisol measurement","C. ACTH stimulation test (Short Synacthen test)","D. CT scan of the adrenal glands"]','A','The overnight 1 mg DST is the standard screening test for Cushing syndrome. Dexamethasone 1 mg given at 23:00; cortisol measured at 08:00-09:00 next morning. Normal: cortisol <50 nmol/L (suppressed). Failure to suppress (cortisol >=50 nmol/L) = positive screen. False positives: alcohol excess, depression, obesity, physical stress, enzyme-inducing drugs (rifampicin, phenytoin, carbamazepine -- increase dexamethasone metabolism, causing apparent non-suppression).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Cushing''s Syndrome — Diagnosis & Management','medium','mcq','After a positive overnight DST, the CONFIRMATORY test for Cushing syndrome is:','["A. Repeat overnight 1 mg DST on a second day","B. Low-dose dexamethasone suppression test (LDDST): 0.5 mg dexamethasone every 6 hours for 2 days","C. High-dose DST: 8 mg overnight dexamethasone","D. CRH stimulation test alone"]','B','LDDST (confirmatory): 0.5 mg dexamethasone orally every 6 hours for 48 hours (total 2 mg). Cortisol measured at 48 hours. Normal response: cortisol <50 nmol/L. In Cushing syndrome: cortisol fails to suppress. This confirms genuine autonomous cortisol excess versus pseudo-Cushing states (depression, obesity, alcoholism). Alternative confirmatory tests: 24-hour urinary free cortisol (x2), late-night salivary cortisol (x2 -- cortisol should be nadir at midnight normally).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Cushing''s Syndrome — Diagnosis & Management','medium','mcq','What does a positive HIGH-DOSE dexamethasone suppression test (8 mg) help determine?','["A. Whether Cushing syndrome is present at all","B. Whether the ACTH source is pituitary (Cushing disease -- suppresses >50%) vs ectopic (does NOT suppress)","C. Whether adrenal CT or MRI should be performed first","D. Whether bilateral or unilateral adrenalectomy is needed"]','B','High-dose DST (8 mg overnight): In Cushing disease (pituitary corticotroph adenoma), some glucocorticoid feedback is preserved -- cortisol suppresses by >50% from baseline. In ectopic ACTH syndrome (small cell lung cancer, carcinoid), cortisol does NOT suppress (autonomous ACTH secretion). Sensitivity ~80%, specificity ~80%. Inferior petrosal sinus sampling (IPSS) is the gold standard for pituitary vs ectopic differentiation and has largely replaced the high-dose DST in many centres.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Cushing''s Syndrome — Diagnosis & Management','easy','mcq','Which clinical features are MOST SPECIFIC for Cushing syndrome, helping distinguish it from simple obesity?','["A. Weight gain and increased appetite","B. Hypertension and type 2 diabetes only (both occur in simple obesity)","C. Fatigue and sleep disturbance alone","D. Purple striae >1 cm wide, proximal myopathy, and easy bruising"]','D','Features most discriminating for Cushing syndrome vs simple obesity: wide (>1 cm) purple/violaceous abdominal striae; proximal muscle weakness (difficulty rising from low chair, climbing stairs -- characteristic); easy bruising with thin atrophic skin; facial plethora; moon face; buffalo hump; supraclavicular fat pads; menstrual irregularities; hypokalaemia; osteoporosis. Simple obesity: pink/white striae, normal muscle strength, no bruising. Proximal myopathy and wide purple striae are the most discriminating features.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Cushing''s Syndrome — Diagnosis & Management','medium','mcq','A patient with ACTH-dependent Cushing syndrome has a normal pituitary MRI. The MOST appropriate next investigation is:','["A. Inferior petrosal sinus sampling (IPSS) with CRH stimulation","B. Repeat pituitary MRI with contrast in 6 months","C. Treat empirically with metyrapone without further investigation","D. Adrenal CT -- she must have an adrenal adenoma if the pituitary is normal"]','A','IPSS is the gold standard for distinguishing pituitary-source ACTH from ectopic ACTH when MRI is normal or equivocal (up to 40% of pituitary corticotroph microadenomas are undetectable on MRI). IPSS measures ACTH simultaneously in both inferior petrosal sinuses (draining the pituitary) and peripheral blood, before and after CRH injection. Central:peripheral ACTH ratio >2 (pre-CRH) or >3 (post-CRH) confirms pituitary source. IPSS also provides lateralisation data to guide surgical approach.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Cushing''s Syndrome — Diagnosis & Management','hard','mcq','What is the TREATMENT OF CHOICE for Cushing disease (ACTH-secreting pituitary adenoma)?','["A. Bilateral adrenalectomy as first-line treatment","B. Transsphenoidal pituitary surgery (selective adenomectomy)","C. Lifelong metyrapone therapy as first choice","D. External beam radiotherapy to the pituitary as first-line"]','B','Transsphenoidal surgery (TSS) by an experienced pituitary neurosurgeon is first-line for Cushing disease. Remission rates: microadenomas 70-90%; macroadenomas 40-60%. Success confirmed by post-operative cortisol <50 nmol/L within 24-48 hours (indicating HPA axis suppression). If TSS fails: (1) Repeat TSS; (2) Pituitary radiotherapy (stereotactic radiosurgery); (3) Bilateral adrenalectomy (risk of Nelson syndrome); (4) Medical therapy (metyrapone, ketoconazole, pasireotide) as bridge or inoperable cases.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Cushing''s Syndrome — Diagnosis & Management','hard','mcq','A patient develops Nelson syndrome after bilateral adrenalectomy. What does this involve?','["A. Rapid enlargement of the residual ACTH-secreting pituitary tumour causing hyperpigmentation and mass effects","B. Hypothyroidism from adrenal-pituitary axis disruption post-operatively","C. Hyperparathyroidism from hypercalcaemia due to increased vitamin D activation","D. Resolution of all Cushing syndrome features within 3 months after surgery"]','A','Nelson syndrome: after bilateral adrenalectomy, removal of cortisol eliminates negative feedback on the pituitary corticotroph tumour. The tumour undergoes accelerated growth, secreting very high levels of ACTH and POMC-derived peptides (including MSH) causing: severe hyperpigmentation, visual field defects (chiasmal compression), headache, and pituitary apoplexy risk. Occurs in 8-43% post-bilateral adrenalectomy. Prevention: pituitary radiotherapy before adrenalectomy. Treatment: transsphenoidal surgery, radiotherapy, temozolomide.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Cushing''s Syndrome — Diagnosis & Management','medium','mcq','What is the BIOCHEMICAL HALLMARK of ACTH-INDEPENDENT Cushing syndrome (adrenal adenoma)?','["A. Elevated ACTH and elevated cortisol (both autonomously raised)","B. Suppressed ACTH (<10 pg/mL) with elevated cortisol","C. Elevated ACTH with low cortisol (suggesting adrenal resistance)","D. Both ACTH and cortisol suppressed (consistent with exogenous steroids)"]','B','ACTH-independent Cushing syndrome (adrenal adenoma or carcinoma): the adrenal tumour autonomously secretes cortisol, which suppresses the hypothalamo-pituitary axis via negative feedback -- ACTH is suppressed (<10 pg/mL) while cortisol is elevated. In ACTH-DEPENDENT Cushing syndrome (pituitary or ectopic), ACTH is inappropriately normal or elevated. Measuring plasma ACTH is the critical first step after confirming Cushing syndrome to determine if ACTH-dependent or independent.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Cushing''s Syndrome — Diagnosis & Management','hard','mcq','A confirmed ACTH-independent Cushing patient has a 3 cm unilateral left adrenal adenoma. The MOST appropriate management is:','["A. Bilateral adrenalectomy -- always remove both adrenals to prevent recurrence","B. Left laparoscopic adrenalectomy with perioperative hydrocortisone cover","C. Medical therapy with metyrapone lifelong -- avoid surgery in all cases","D. Pituitary MRI to exclude a concurrent corticotroph adenoma first"]','B','Unilateral adrenal adenoma causing ACTH-independent Cushing syndrome: treated by laparoscopic adrenalectomy of the affected side. Perioperative hydrocortisone cover is ESSENTIAL: the contralateral adrenal has been suppressed by chronic hypercortisolaemia and is atrophic; it cannot respond to surgical stress without exogenous steroid. Post-operatively: hydrocortisone replacement required for months to years while the HPA axis recovers. Short Synacthen Test (SST) is used to assess HPA axis recovery before weaning steroids.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Cushing''s Syndrome — Diagnosis & Management','medium','mcq','Which drug is used for MEDICAL MANAGEMENT of Cushing syndrome while awaiting surgery or in inoperable cases?','["A. Metyrapone (11-beta-hydroxylase inhibitor -- reduces cortisol synthesis)","B. Fludrocortisone (mineralocorticoid -- replaces aldosterone, not used in Cushing)","C. Propylthiouracil (PTU -- inhibits thyroid hormone synthesis)","D. Spironolactone (aldosterone antagonist)"]','A','Medical management of Cushing syndrome uses steroidogenesis inhibitors: Metyrapone (11-beta-hydroxylase inhibitor) -- most widely used in the UK; reduces cortisol synthesis; side effects: hirsutism, hypertension (from mineralocorticoid precursor accumulation), hypokalaemia. Ketoconazole (multiple enzyme inhibition) -- hepatotoxicity risk. Osilodrostat (newer, potent 11-beta-hydroxylase inhibitor). Pasireotide (somatostatin analogue) -- for Cushing disease (reduces ACTH from corticotroph adenomas). Mifepristone (glucocorticoid receptor antagonist) -- for associated hyperglycaemia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Adrenal Insufficiency','easy','mcq','A patient with known Addison disease presents with hypotension, vomiting, and confusion -- Addisonian crisis. The IMMEDIATE treatment is:','["A. Oral hydrocortisone 20 mg and oral fluid replacement","B. IV (or IM) hydrocortisone 100 mg stat, then IV 0.9% NaCl resuscitation","C. IV fludrocortisone 100 mg stat","D. IV dexamethasone 8 mg with fluid restriction"]','B','Addisonian crisis management: (1) IV hydrocortisone 100 mg STAT (IM if IV access delayed); then 50-100 mg q6-8h or 200 mg/24h continuous IV infusion; (2) IV 0.9% NaCl -- 1 L over 30-60 min for hypotension, then further resuscitation as needed; (3) Add 5% or 10% dextrose if hypoglycaemic. Do NOT wait for cortisol results before treating. Fludrocortisone is NOT needed acutely -- hydrocortisone at high doses has adequate mineralocorticoid activity. Once stable, convert to oral hydrocortisone and add fludrocortisone.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Adrenal Insufficiency','easy','mcq','Which biochemical pattern is CHARACTERISTIC of primary adrenal insufficiency (Addison disease)?','["A. Hyponatraemia, hyperkalaemia, hypoglycaemia, low cortisol, and elevated ACTH","B. Hypernatraemia, hypokalaemia, high cortisol, and suppressed ACTH","C. Normal electrolytes, low ACTH, low cortisol (secondary adrenal insufficiency pattern)","D. Elevated aldosterone, low renin, hypertension (primary hyperaldosteronism pattern)"]','A','Primary adrenal insufficiency: cortisol AND aldosterone are deficient. Aldosterone deficiency: Na+ loss (hyponatraemia), K+ retention (hyperkalaemia). Cortisol deficiency: hypoglycaemia, loss of negative feedback -- markedly elevated ACTH (and MSH) causing hyperpigmentation (skin creases, buccal mucosa, gingiva, nipples, scars). In secondary adrenal insufficiency (ACTH deficiency): cortisol is low, ACTH is also low, aldosterone is INTACT (regulated by renin-angiotensin, not ACTH), no hyperpigmentation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Adrenal Insufficiency','medium','mcq','What is the GOLD STANDARD diagnostic test for adrenal insufficiency?','["A. Random serum cortisol <100 nmol/L on a single measurement","B. 24-hour urinary free cortisol","C. Short Synacthen Test (SST): 250 mcg ACTH IV or IM -- peak cortisol >550 nmol/L at 30 or 60 min is normal","D. Overnight dexamethasone suppression test"]','C','The Short Synacthen Test (SST) is the gold standard. ACTH analogue (tetracosactide 250 mcg) given IV or IM; cortisol measured at 0, 30, 60 minutes. Normal: peak cortisol >550 nmol/L (or >500 nmol/L by some assays). Failure confirms adrenal insufficiency. Simultaneous basal ACTH measurement (at 0 minutes) differentiates: primary (ACTH >100 pg/mL -- elevated) vs secondary (ACTH low/normal). Early morning basal cortisol <100 nmol/L is almost diagnostic of insufficiency.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Adrenal Insufficiency','medium','mcq','A patient with Addison disease is scheduled for major abdominal surgery. What perioperative steroid management is required?','["A. Continue oral hydrocortisone at usual dose -- surgery does not affect requirements significantly","B. Stop hydrocortisone 24 hours pre-op to allow anaesthesia team flexibility","C. Double oral hydrocortisone for 48 hours post-op only","D. IV hydrocortisone 100 mg at induction, then 50 mg q6-8h IV for 24-48 hours, then step-down to oral"]','D','Perioperative steroid cover for major surgery in Addison disease: (1) IV hydrocortisone 100 mg at induction of anaesthesia; (2) 50 mg IV q6-8h for 24-48 hours post-op; (3) Step down to oral hydrocortisone when patient can eat, with gradual reduction to maintenance over 3-5 days. Inform anaesthetist and ward staff. Surgical stress dramatically increases cortisol requirements (normally 10-20 mg/day -- need 200-400 mg/day during major surgery). Never withhold steroids perioperatively.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Adrenal Insufficiency','hard','mcq','What maintenance doses of hydrocortisone and fludrocortisone are standard for Addison disease?','["A. Hydrocortisone 15-25 mg/day in divided doses (largest AM dose) + fludrocortisone 50-300 mcg once daily","B. Hydrocortisone 100 mg daily + fludrocortisone 1 mg daily","C. Prednisolone 40 mg daily alone (no fludrocortisone needed in Addison disease)","D. Dexamethasone 8 mg daily as sole steroid replacement"]','A','Maintenance replacement for Addison disease: Hydrocortisone 15-25 mg/day, typically divided as 10 mg on waking, 5 mg at noon, 5 mg at 15:00-16:00 (mimicking physiological cortisol diurnal rhythm). Do NOT take a late evening dose (disrupts sleep). Fludrocortisone 50-300 mcg (mean ~100 mcg) once daily for mineralocorticoid (aldosterone) replacement -- prevents salt wasting and hyperkalaemia. Adequacy monitored by electrolytes, blood pressure (lying/standing), and renin levels.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Adrenal Insufficiency','easy','mcq','A patient with Addison disease develops fever (38.8 degrees C) and gastroenteritis with vomiting. What sick-day rules must she follow?','["A. Halve steroid dose to avoid immune suppression during infection","B. Stop hydrocortisone until vomiting resolves to prevent fluid retention","C. Double or triple oral hydrocortisone during illness; attend hospital for IM/IV hydrocortisone if unable to take orally","D. Take only fludrocortisone during gastroenteritis -- hydrocortisone is not needed"]','C','Sick-day rules for Addison disease: DOUBLE or TRIPLE oral hydrocortisone during ANY illness, fever, or significant physiological stress. If vomiting prevents oral absorption, the patient MUST attend hospital for IM hydrocortisone 100 mg immediately. Delaying IV/IM steroids in a vomiting Addison patient rapidly leads to Addisonian crisis (hypotension, shock, death). All patients should carry: steroid emergency card, IM hydrocortisone kit (100 mg pre-loaded), and medical alert bracelet/card.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Adrenal Insufficiency','hard','mcq','What is the MOST COMMON cause of primary adrenal insufficiency in developed countries?','["A. Tuberculosis adrenalitis (bilateral adrenal destruction by TB)","B. Autoimmune adrenalitis (autoimmune Addison disease)","C. Meningococcal septicaemia (Waterhouse-Friderichsen syndrome)","D. Adrenal metastases from lung or breast cancer"]','B','Autoimmune adrenalitis accounts for ~80% of primary adrenal insufficiency in developed countries. Cell-mediated and humoral destruction of adrenal cortical cells, with 21-hydroxylase antibodies in ~90%. Often in context of Autoimmune Polyendocrine Syndrome: APS-2 (Addison + Type 1 DM + Hashimoto) -- most common; APS-1 (Addison + hypoparathyroidism + mucocutaneous candidiasis). In developing countries: tuberculosis remains most common cause (calcified adrenals on CT).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Adrenal Insufficiency','medium','mcq','How does SECONDARY adrenal insufficiency (hypopituitarism/ACTH deficiency) differ from PRIMARY Addison disease?','["A. Secondary adrenal insufficiency requires higher hydrocortisone doses than Addison disease","B. Aldosterone secretion is PRESERVED in secondary adrenal insufficiency -- fludrocortisone is NOT needed","C. Hyperpigmentation is MORE prominent in secondary adrenal insufficiency","D. The Short Synacthen Test is always normal in secondary adrenal insufficiency"]','B','Secondary adrenal insufficiency: ACTH deficiency from pituitary disease -- cortisol is low but the renin-angiotensin-aldosterone system is intact (aldosterone regulated by angiotensin II and K+, not ACTH). Therefore: NO aldosterone deficiency, fludrocortisone NOT required, electrolytes usually normal. ACTH (and co-secreted MSH) is LOW -- no hyperpigmentation. The SST can appear normal acutely after pituitary insult (adrenal atrophy takes 2-4 weeks to develop).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Adrenal Insufficiency','hard','mcq','When adrenal crisis is suspected but diagnosis is unconfirmed, which steroid is preferred and why?','["A. Hydrocortisone -- it is the most physiological replacement steroid available","B. Dexamethasone 4 mg IV -- it does not cross-react with cortisol immunoassay, allowing diagnosis while treating","C. Prednisolone -- it has the best mineralocorticoid activity for acute use","D. Fludrocortisone IV -- safest for acute use before diagnosis is confirmed"]','B','When adrenal crisis is suspected but unconfirmed, IV dexamethasone 4 mg is given instead of hydrocortisone. Dexamethasone does NOT cross-react with cortisol in standard cortisol immunoassays, allowing a Short Synacthen Test (SST) to be performed while the patient is being treated. This allows simultaneous treatment and diagnosis. Once the SST is completed, switch to hydrocortisone (which has mineralocorticoid activity and is the appropriate ongoing replacement).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Adrenal Insufficiency','hard','mcq','A patient on long-term prednisolone 10 mg/day for rheumatoid arthritis has major surgery and becomes hypotensive with low cortisol 6 hours post-op. This represents:','["A. Septic shock from surgical site infection","B. Secondary adrenal insufficiency from HPA axis suppression by exogenous steroids -- steroid-induced adrenal crisis","C. Primary Addison disease unrelated to prednisolone therapy","D. Anaphylaxis to anaesthetic agents used during surgery"]','B','Long-term exogenous glucocorticoids suppress the HPA axis by negative feedback, causing secondary adrenal insufficiency. Duration and dose: >5 mg prednisolone equivalent for >4 weeks carries risk of HPA suppression. Surgical stress dramatically increases cortisol requirements -- if the suppressed HPA axis cannot respond, Addisonian crisis results. Management: perioperative steroid cover (hydrocortisone 25-100 mg depending on surgical severity). All patients on long-term steroids must be identified pre-operatively and given appropriate steroid cover.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Primary Hyperaldosteronism','easy','mcq','What is the SCREENING TEST for primary hyperaldosteronism (Conn syndrome)?','["A. 24-hour urinary sodium excretion","B. Aldosterone-to-renin ratio (ARR) -- elevated ARR suggests primary hyperaldosteronism","C. Overnight dexamethasone suppression test","D. Short Synacthen test (ACTH stimulation)"]','B','The aldosterone-to-renin ratio (ARR) is the preferred screening test for primary hyperaldosteronism. In primary hyperaldosteronism, aldosterone is elevated and renin is suppressed (by volume expansion), giving a markedly elevated ARR. Conditions for testing: ideally stop interfering medications 2-4 weeks before (spironolactone, eplerenone, amiloride, diuretics). Beta-blockers and ACE inhibitors can be continued but affect interpretation. A positive ARR requires confirmatory testing.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Primary Hyperaldosteronism','medium','mcq','What is the CLASSIC biochemical triad of primary hyperaldosteronism?','["A. Hypertension, hyperkalaemia, and elevated renin","B. Hypertension, hypokalaemia, and suppressed renin with elevated aldosterone","C. Hypotension, hypernatraemia, and low aldosterone","D. Hypertension, hypernatraemia, and elevated ACTH"]','B','Primary hyperaldosteronism: autonomous aldosterone secretion causes: (1) Hypertension (Na+ and water retention -- volume expansion); (2) Hypokalaemia (aldosterone drives K+ excretion in collecting duct in exchange for Na+); (3) Metabolic alkalosis (H+ loss). Renin is SUPPRESSED by volume expansion. NOTE: hypokalaemia is present in only ~50% of patients -- many present with hypertension alone or resistant hypertension. Primary hyperaldosteronism accounts for 5-10% of all hypertension.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Primary Hyperaldosteronism','medium','mcq','After a positive ARR, which test CONFIRMS autonomous aldosterone secretion?','["A. Repeat ARR on a different day","B. Pituitary MRI to exclude ACTH-dependent mechanism","C. Fludrocortisone suppression test OR intravenous saline suppression test (salt loading)","D. Genetic testing for KCNJ5 mutation as first line"]','C','Confirmatory tests for primary hyperaldosteronism: (1) IV saline suppression test: 2 L 0.9% NaCl over 4 hours; aldosterone failure to suppress <140 pmol/L is diagnostic; (2) Fludrocortisone suppression test (FST): oral fludrocortisone for 4 days; failure of aldosterone to suppress <170 pmol/L confirms autonomous secretion; (3) Oral salt loading test; (4) Captopril challenge test. CT adrenals is performed AFTER biochemical confirmation to localise the source.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Primary Hyperaldosteronism','hard','mcq','After biochemical confirmation of primary hyperaldosteronism, CT adrenals shows a 1.2 cm right adrenal adenoma. What is the CRITICAL next step before surgery?','["A. Proceed directly to right laparoscopic adrenalectomy -- CT confirms the diagnosis and side","B. Perform bilateral adrenalectomy -- CT underestimates bilateral disease","C. Start lifelong spironolactone -- surgery is not indicated for adenomas","D. Adrenal vein sampling (AVS) to confirm unilateral aldosterone excess before committing to surgery"]','D','AVS is MANDATORY before surgery because CT has ~50% false-localisation rate in primary hyperaldosteronism -- apparent unilateral adenomas on CT may be bilateral hyperplasia (which is treated medically, not surgically). AVS measures aldosterone:cortisol ratio from both adrenal veins vs peripheral blood simultaneously. Lateralisation ratio >4:1 (post-ACTH stimulation) confirms unilateral aldosterone excess -- indicating adrenalectomy will be curative. Without AVS, up to 25% of patients would undergo unnecessary surgery.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Primary Hyperaldosteronism','easy','mcq','What is the FIRST-LINE medical treatment for primary hyperaldosteronism in patients not suitable for surgery?','["A. Spironolactone (mineralocorticoid receptor antagonist)","B. Fludrocortisone (synthetic mineralocorticoid -- worsens primary hyperaldosteronism)","C. Dexamethasone suppression therapy","D. Amlodipine calcium channel blocker alone"]','A','Spironolactone is first-line medical therapy for primary hyperaldosteronism. As a competitive mineralocorticoid receptor antagonist, it blocks aldosterone effects on the collecting duct, reducing Na+ retention, K+ wasting, hypertension, and metabolic alkalosis. Starting dose: 25-50 mg/day, titrating to 100-400 mg/day. Side effects: gynaecomastia, mastodynia, menstrual irregularities, hyperkalaemia. Eplerenone (more selective -- fewer sex hormone side effects) is an alternative. Monitor potassium and renal function.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Primary Hyperaldosteronism','medium','mcq','What is the MOST COMMON subtype of primary hyperaldosteronism?','["A. Unilateral aldosterone-producing adenoma (Conn adenoma) -- ~35% of cases","B. Bilateral idiopathic adrenal hyperplasia (BAH) -- ~60-65% of cases","C. Adrenal carcinoma with autonomous aldosterone secretion","D. Familial hyperaldosteronism type I (glucocorticoid-remediable)"]','B','Bilateral idiopathic adrenal hyperplasia (BAH) is the most common subtype (~60-65%). Unilateral aldosterone-producing adenoma (APA/Conn adenoma) accounts for ~30-35%. This distinction is critically important: APA is treated by laparoscopic adrenalectomy (potentially curative of hypertension and hypokalaemia); BAH is treated medically with spironolactone or eplerenone (surgery does not cure hypertension in bilateral disease). AVS determines the subtype with greater accuracy than CT alone.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Primary Hyperaldosteronism','hard','mcq','Which ELECTROLYTE abnormality must be monitored after laparoscopic adrenalectomy for unilateral primary hyperaldosteronism?','["A. Hypercalcaemia from incidental parathyroid disruption during surgery","B. Hyperkalaemia -- the contralateral zona glomerulosa is suppressed and cannot immediately compensate","C. Hyponatraemia from inappropriate ADH secretion (SIADH)","D. Hypernatraemia from impaired water regulation post-surgery"]','B','Post-adrenalectomy hyperkalaemia: chronic autonomous aldosterone secretion from the adenoma suppresses renin and the contralateral adrenal zona glomerulosa. After adenoma removal, aldosterone levels drop precipitously but the contralateral zona glomerulosa takes weeks to months to recover. This transient hypoaldosteronism causes K+ retention (hyperkalaemia) and salt wasting (hyponatraemia, hypotension). Monitor K+ and Na+ closely. Temporary fludrocortisone supplementation may be needed. Spironolactone should be stopped pre-operatively.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Primary Hyperaldosteronism','medium','mcq','How does PRIMARY hyperaldosteronism differ biochemically from SECONDARY hyperaldosteronism?','["A. Primary: high aldosterone, HIGH renin; Secondary: high aldosterone, LOW renin","B. Primary: high aldosterone, LOW renin; Secondary: high aldosterone, HIGH renin","C. Both primary and secondary hyperaldosteronism have identical renin levels","D. Primary: low aldosterone; Secondary: high aldosterone"]','B','Primary hyperaldosteronism: autonomous (renin-independent) aldosterone excess -- elevated aldosterone + SUPPRESSED renin + HIGH ARR. Secondary hyperaldosteronism: aldosterone is elevated BECAUSE renin is elevated (appropriate response to reduced renal perfusion or volume depletion: renal artery stenosis, diuretics, heart failure, cirrhosis, nephrotic syndrome) -- BOTH aldosterone AND renin are elevated -- ARR is NORMAL or LOW. The ARR is the critical distinguishing investigation.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Primary Hyperaldosteronism','hard','mcq','Which rare genetic subtype of primary hyperaldosteronism is treated with low-dose dexamethasone?','["A. Familial Hyperaldosteronism Type I (FH-I) -- glucocorticoid-remediable aldosteronism (GRA)","B. Familial Hyperaldosteronism Type II (bilateral APA with familial inheritance)","C. Bilateral idiopathic adrenal hyperplasia (most common subtype)","D. APA associated with MEN1 syndrome"]','A','FH-I (glucocorticoid-remediable aldosteronism/GRA) is caused by a chimeric fusion gene (CYP11B1/CYP11B2) placing aldosterone synthase under ACTH regulatory control. Result: aldosterone secretion is driven by ACTH rather than angiotensin II. Treatment: low-dose dexamethasone (0.125-0.25 mg/day) suppresses ACTH, thereby suppressing aldosterone -- correcting hypertension and hypokalaemia. Suspect in patients <40 years with primary hyperaldosteronism and family history of early-onset hypertension or haemorrhagic stroke.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Primary Hyperaldosteronism','hard','mcq','A 38-year-old with primary hyperaldosteronism refuses surgery. K+ is 2.8 mmol/L. In addition to spironolactone, what should be prescribed?','["A. Furosemide (loop diuretic) -- to promote natriuresis and reduce volume overload","B. Oral potassium chloride supplementation (40-80 mmol/day) until K+ normalises on spironolactone","C. Fludrocortisone -- to replace the mineralocorticoid deficiency","D. Amiloride alone as a replacement for spironolactone"]','B','In primary hyperaldosteronism with hypokalaemia, spironolactone corrects K+ wasting by blocking the mineralocorticoid receptor. However, while K+ is being corrected (which can take weeks to reach steady state), oral KCl supplementation (40-80 mmol/day in divided doses) should be prescribed to replenish K+ stores rapidly. Monitor K+ at 2-4 weeks. Furosemide worsens K+ loss. Fludrocortisone would worsen the situation (additional mineralocorticoid activity). Once adequately dosed on spironolactone, K+ supplementation can usually be reduced.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Acromegaly & Pituitary Disease','easy','mcq','What is the BEST SCREENING TEST for acromegaly?','["A. Random serum growth hormone (GH) level","B. Serum insulin-like growth factor-1 (IGF-1), adjusted for age and sex","C. Pituitary MRI -- identifies the adenoma directly","D. 24-hour urinary GH excretion"]','B','IGF-1 is the best screening test for acromegaly. Produced in the liver under GH stimulation, IGF-1 reflects integrated 24-hour GH secretion (unlike pulsatile random GH). IGF-1 is compared to age- and sex-adjusted reference ranges. Elevated IGF-1 = strong evidence for GH excess. A normal IGF-1 effectively excludes acromegaly. Random GH is unreliable due to physiological pulsatile secretion and elevation with exercise, stress, and hypoglycaemia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Acromegaly & Pituitary Disease','medium','mcq','What is the GOLD STANDARD CONFIRMATORY TEST for acromegaly?','["A. Pituitary MRI demonstrating a GH-secreting adenoma","B. Oral glucose tolerance test (OGTT) with GH measurement -- GH should suppress to <1 mcg/L (or <0.4 mcg/L with newer assays)","C. Random GH >5 mcg/L on three separate occasions","D. 24-hour urinary GH collection"]','B','OGTT with GH measurement: 75 g oral glucose suppresses GH to <1 mcg/L (ultra-sensitive assays: <0.4 mcg/L) in healthy individuals. In acromegaly: GH fails to suppress (remains elevated or paradoxically rises). The test is performed after IGF-1 is found elevated. Combination of elevated IGF-1 + non-suppressed GH on OGTT confirms acromegaly. GH nadir <1 mcg/L on OGTT after treatment indicates biochemical remission.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Acromegaly & Pituitary Disease','medium','mcq','After biochemical confirmation of acromegaly, what is the NEXT investigation?','["A. CT chest/abdomen to exclude ectopic GH source","B. Inferior petrosal sinus sampling","C. Pituitary MRI with gadolinium contrast","D. Adrenal CT to exclude GH-stimulated adrenal disease"]','C','Pituitary MRI with gadolinium contrast is the next step after biochemical confirmation of acromegaly. It identifies and characterises the GH-secreting somatotroph adenoma: 95% of acromegaly is caused by a pituitary adenoma. MRI assesses tumour size (micro <1 cm; macro >1 cm -- most are macroadenomas due to delayed diagnosis), cavernous sinus invasion (predicts surgical difficulty), and optic chiasm relationship (guides urgency). Ectopic GH secretion is extremely rare (<1%).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Acromegaly & Pituitary Disease','easy','mcq','What is the FIRST-LINE treatment for acromegaly caused by a pituitary GH-secreting adenoma?','["A. Lifelong octreotide LAR injections (somatostatin analogue)","B. Transsphenoidal surgery to remove the GH-secreting pituitary adenoma","C. External beam pituitary radiotherapy","D. Cabergoline (dopamine agonist monotherapy)"]','B','Transsphenoidal surgery (TSS) is first-line for acromegaly. Biochemical remission rates: microadenomas 70-90%; macroadenomas 40-60%. Post-operative remission: IGF-1 normalises AND GH suppresses to <1 mcg/L on OGTT. For residual/recurrent disease: somatostatin analogues (octreotide LAR, lanreotide autogel) are the primary medical therapy. Pegvisomant (GH receptor antagonist) is used when IGF-1 remains elevated on somatostatin analogues.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Acromegaly & Pituitary Disease','hard','mcq','Which is the MOST COMMON cause of premature death in untreated acromegaly?','["A. Cardiovascular disease (cardiomegaly, hypertension, arrhythmias, coronary artery disease)","B. Pituitary apoplexy","C. Adrenal insufficiency from hypopituitarism","D. Colorectal carcinoma"]','A','Cardiovascular disease accounts for ~60% of premature mortality in acromegaly. Mechanisms: GH/IGF-1 excess causes biventricular concentric hypertrophy, diastolic dysfunction, hypertension (~30-40%), arrhythmias (AF, ventricular), and accelerated atherosclerosis. Acromegaly doubles mortality. Effective treatment (normalising IGF-1) significantly improves cardiac structure and function and reduces mortality to near-normal. Other risks: sleep apnoea, colorectal polyps/cancer (increased surveillance recommended), arthropathy, carpal tunnel.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Acromegaly & Pituitary Disease','medium','mcq','Which clinical features are CHARACTERISTIC of acromegaly (GH/IGF-1 excess after epiphyseal closure)?','["A. Weight loss, thin skin, and hypotension","B. Coarsening of facial features, enlarging hands/feet, prognathism, macroglossia, hyperhidrosis, carpal tunnel syndrome","C. Exophthalmos, lid retraction, and pretibial myxoedema (Graves ophthalmopathy features)","D. Moon face, buffalo hump, purple striae (Cushing syndrome features)"]','B','Acromegaly features: coarsening facial features, frontal bossing, prognathism (protruding jaw), macroglossia, interdental spacing; increased ring/shoe size (patients notice rings and shoes no longer fitting); hyperhidrosis (excessive sweating); carpal tunnel syndrome; sleep apnoea; arthralgia; hypertension; glucose intolerance/diabetes; visual field defects if chiasmal compression. Pre-epiphyseal excess causes gigantism (excessive linear growth). Options C and D describe Graves ophthalmopathy and Cushing syndrome respectively.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Acromegaly & Pituitary Disease','hard','mcq','A patient with a large pituitary macroadenoma (>3 cm) presents acutely with thunderclap headache, diplopia, and right ptosis. This emergency is:','["A. Subarachnoid haemorrhage -- lumbar puncture and IV nimodipine immediately","B. Pituitary apoplexy -- emergency IV hydrocortisone 100 mg stat + urgent neurosurgical review","C. Meningitis -- immediate IV antibiotics and dexamethasone","D. Migraine with aura -- IV sumatriptan and anti-emetics"]','B','Pituitary apoplexy: haemorrhage or infarction into a pituitary adenoma causing sudden severe headache (thunderclap), visual field defects (bitemporal hemianopia), diplopia/ophthalmoplegia (CN III, IV, VI palsy from cavernous sinus compression), acute hypopituitarism. Management: (1) IV hydrocortisone 100 mg stat -- acute ACTH/cortisol deficiency is immediately life-threatening; (2) Urgent neurosurgical assessment for trans-sphenoidal decompression if vision is threatened; (3) Intensive monitoring; (4) MRI pituitary.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Acromegaly & Pituitary Disease','medium','mcq','Bitemporal hemianopia from a pituitary macroadenoma is caused by compression of which structure?','["A. Optic radiation in the temporal lobes bilaterally","B. Optic chiasm -- where nasal fibres (carrying temporal visual fields) decussate","C. Third cranial nerve (CN III) at the posterior communicating artery","D. Lateral geniculate nucleus (thalamus)"]','B','The optic chiasm lies directly superior to the pituitary fossa. A superiorly expanding pituitary macroadenoma compresses the optic chiasm, particularly its decussating nasal fibres (carrying temporal visual field information from both eyes). This produces bitemporal hemianopia (loss of both temporal/outer visual fields) -- the classic visual field defect in pituitary tumours. Formal visual field testing (Humphrey automated perimetry) and urgent MRI are required. Untreated compression causes progressive and potentially irreversible visual loss.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Acromegaly & Pituitary Disease','easy','mcq','In panhypopituitarism, which hormone deficiency is MOST IMMEDIATELY life-threatening and must be replaced FIRST?','["A. Growth hormone deficiency","B. TSH deficiency (central hypothyroidism)","C. LH/FSH deficiency (hypogonadism)","D. ACTH deficiency (secondary adrenal insufficiency)"]','D','ACTH deficiency (causing secondary cortisol deficiency) is the most immediately life-threatening hormone deficiency in hypopituitarism. Cortisol is essential for vascular tone and stress response. Critical rule: ALWAYS replace hydrocortisone BEFORE levothyroxine -- thyroid hormone accelerates cortisol metabolism; starting T4 without cortisol replacement can precipitate an Addisonian crisis. GH deficiency and gonadotrophin deficiency are important for quality of life but are not acutely life-threatening.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Acromegaly & Pituitary Disease','hard','mcq','Which medical therapy is used when acromegaly persists or recurs after surgery, and how does it work?','["A. Cabergoline (dopamine agonist) -- first-line post-surgical medical therapy for all patients","B. Octreotide LAR or lanreotide autogel (somatostatin analogues) -- suppress GH/IGF-1 and can reduce tumour size","C. Metformin -- reduces IGF-1 levels by improving insulin sensitivity","D. Bromocriptine -- same efficacy as somatostatin analogues in acromegaly"]','B','Somatostatin analogues (octreotide LAR 10-40 mg IM monthly; lanreotide autogel 60-120 mg SC monthly) are the primary medical therapy for persistent/recurrent acromegaly after surgery. Mechanism: bind somatostatin receptors (especially SSTR2 and SSTR5) on somatotroph tumours, inhibiting GH secretion; also reduce tumour volume. Biochemical response (IGF-1 normalisation) in ~50-70% of patients. Pegvisomant (GH receptor antagonist) is added or substituted if IGF-1 remains elevated. Radiotherapy is a third-line option.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Calcium Disorders','easy','mcq','What is the MOST COMMON cause of hypercalcaemia in the outpatient (community) setting?','["A. Malignancy -- PTHrP secretion or osteolytic metastases","B. Primary hyperparathyroidism -- solitary parathyroid adenoma","C. Vitamin D toxicity from supplementation","D. Sarcoidosis -- excess 1,25-dihydroxyvitamin D from activated macrophages"]','B','Primary hyperparathyroidism is the most common cause of hypercalcaemia in the OUTPATIENT setting (~55%). Usually caused by a solitary parathyroid adenoma (~85%), causing autonomous PTH secretion that mobilises calcium from bone, increases renal tubular Ca2+ reabsorption, and stimulates 1,25-dihydroxyvitamin D production (increasing gut absorption). Often asymptomatic and found incidentally. Malignancy is the most common cause of hypercalcaemia in HOSPITALISED patients.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Calcium Disorders','medium','mcq','A patient with hypercalcaemia (Ca2+ 3.4 mmol/L) has a suppressed PTH. What is the MOST LIKELY cause?','["A. Primary hyperparathyroidism (elevated PTH)","B. Familial hypocalciuric hypercalcaemia (FHH -- elevated or normal PTH)","C. Malignancy-associated hypercalcaemia (elevated PTHrP or osteolytic bone metastases)","D. Tertiary hyperparathyroidism from chronic renal failure (elevated PTH)"]','C','Hypercalcaemia with SUPPRESSED PTH (<1.0 pmol/L) suggests a non-PTH-mediated mechanism: malignancy (PTHrP from squamous cell carcinoma, breast, renal, bladder, multiple myeloma with direct bone lysis), vitamin D toxicity, granulomatous disease (sarcoidosis, TB -- excess 1,25-dihydroxyvitamin D from macrophages), thyrotoxicosis, immobilisation, milk-alkali syndrome. Next step: measure PTHrP and screen for malignancy. Elevated PTH would suggest primary/tertiary hyperparathyroidism or FHH.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Calcium Disorders','medium','mcq','Which ECG change is CLASSICALLY associated with significant hypercalcaemia?','["A. Prolonged QT interval","B. Widened QRS complex and tall peaked T waves","C. Shortened QT interval","D. Delta waves and short PR interval (Wolff-Parkinson-White pattern)"]','C','Hypercalcaemia shortens the QT interval. Calcium stabilises cardiac membranes and accelerates ventricular repolarisation. Mnemonic: "Calcium is Short -- Ca2+ causes short QT." Severe hypercalcaemia may also cause bradycardia, PR prolongation, and cardiac arrest. Hypocalcaemia causes PROLONGED QT, risking torsades de pointes. Peaked T waves and widened QRS are hallmarks of hyperkalaemia. Monitoring ECG in significant hypercalcaemia (Ca2+ >3.0 mmol/L) is essential.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Calcium Disorders','medium','mcq','What is the IMMEDIATE FIRST-LINE treatment for severe symptomatic hypercalcaemia (corrected Ca2+ >3.0 mmol/L)?','["A. IV bisphosphonate (zoledronic acid) immediately without IV fluids first","B. Oral calcium restriction and outpatient monitoring","C. Emergency parathyroidectomy under general anaesthesia","D. IV 0.9% NaCl aggressive rehydration -- the first and most critical priority"]','D','Severe hypercalcaemia management: (1) FIRST: IV 0.9% NaCl aggressive rehydration (2-4 L/24h) -- hypercalcaemia causes nephrogenic diabetes insipidus and dehydration, worsening hypercalcaemia (reduced GFR -- less calcium excretion). Rehydration alone can lower Ca2+ by 0.25-0.75 mmol/L. (2) THEN: IV zoledronic acid 4 mg over 15 min (or pamidronate 60-90 mg over 2h) AFTER hydration -- inhibits osteoclast activity; peak effect 48-72h. (3) Calcitonin 4-8 IU/kg for rapid short-term lowering while bisphosphonate takes effect.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Calcium Disorders','easy','mcq','Which mnemonic describes the classic symptoms of hypercalcaemia?','["A. Bones, Stones, Groans, and Psychic Moans -- bone pain, renal stones, GI symptoms, neuropsychiatric features","B. Hot, bothered, and breathless -- thyrotoxicosis symptoms","C. Chvostek, Trousseau, and tetany -- hypocalcaemia signs","D. Confusion, hypotension, and tachycardia -- sepsis triad"]','A','"Bones, Stones, Groans, and Psychic Moans" covers hypercalcaemia: Bones -- bone pain, pathological fractures, subperiosteal resorption (osteitis fibrosa cystica in severe hyperparathyroidism); Stones -- renal calculi (calcium oxalate/phosphate), nephrocalcinosis, polyuria/polydipsia (nephrogenic DI from hypercalcaemia); Groans -- GI symptoms (nausea, vomiting, constipation, anorexia, peptic ulcers); Psychic Moans -- depression, cognitive impairment, psychosis, weakness, coma (severe cases).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Calcium Disorders','medium','mcq','A patient with hypocalcaemia (Ca2+ 1.65 mmol/L) has an elevated PTH. The MOST LIKELY cause is:','["A. Hypoparathyroidism -- PTH is absent or very low","B. Pseudohypoparathyroidism -- PTH resistance (elevated PTH, low Ca2+, high phosphate)","C. Vitamin D deficiency -- PTH is appropriately elevated as compensatory secondary hyperparathyroidism","D. Malignancy suppressing PTH secretion"]','C','Hypocalcaemia with ELEVATED PTH = secondary hyperparathyroidism (compensatory). Most common cause worldwide: vitamin D deficiency -- low vitamin D impairs intestinal calcium absorption -- hypocalcaemia -- compensatory PTH elevation -- bone resorption and renal calcium reabsorption to correct calcium. Other causes: CKD (impaired 1-alpha-hydroxylase), malabsorption, pseudohypoparathyroidism (PTH resistance -- Albright hereditary osteodystrophy). Hypoparathyroidism: hypocalcaemia with LOW PTH (absent PTH).','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Calcium Disorders','hard','mcq','A patient develops hypocalcaemia 24 hours after total thyroidectomy. Corrected Ca2+ 1.70 mmol/L with perioral tingling and positive Trousseau sign. The MOST LIKELY cause is:','["A. Inadvertent removal or devascularisation of parathyroid glands during surgery","B. Hypothyroidism causing calcium to shift intracellularly","C. Excess calcitonin secretion from the surgical scar tissue","D. Perioperative fluid dilution of serum calcium"]','A','Post-thyroidectomy hypoparathyroidism: parathyroid glands (normally 4) are located on the posterior thyroid capsule and may be inadvertently excised or devascularised during total thyroidectomy. Without PTH: reduced renal calcium reabsorption, reduced bone resorption, reduced 1,25-dihydroxyvitamin D synthesis -- hypocalcaemia. May be transient (<6 months -- recovers) or permanent (>6 months). Incidence: transient ~20-30%; permanent ~1-2% after total thyroidectomy. Treatment: IV calcium gluconate for acute symptoms, then oral calcium + calcitriol.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Calcium Disorders','easy','mcq','Which clinical signs indicate LATENT TETANY in hypocalcaemia?','["A. Chvostek sign (facial twitching on tapping CN VII) and Trousseau sign (carpal spasm with BP cuff inflation)","B. Kernig sign and Brudzinski sign (meningeal irritation)","C. Lhermitte sign (electric shock on neck flexion) and Babinski sign","D. Hoffmann sign and Romberg sign"]','A','Chvostek sign: tapping over the facial nerve (anterior to the tragus) causes ipsilateral facial muscle twitching -- neuromuscular hyperexcitability from hypocalcaemia (sensitivity ~70%, specificity ~90%). Trousseau sign: inflating a BP cuff above systolic for 3 minutes causes carpal spasm ("obstetrician hand" -- wrist flexion, MCP flexion, IP extension, thumb adduction). These indicate latent tetany and require urgent calcium measurement. Also: perioral paraesthesia, muscle cramps, laryngospasm, prolonged QT on ECG.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Calcium Disorders','hard','mcq','How is CORRECTED (adjusted) calcium calculated in a patient with hypoalbuminaemia?','["A. Corrected Ca2+ = measured Ca2+ + 0.02 x (40 - albumin in g/L)","B. Corrected Ca2+ = measured Ca2+ x (albumin/40)","C. No correction is needed -- only ionised calcium is ever used clinically","D. Corrected Ca2+ = measured Ca2+ - 0.02 x (40 - albumin)"]','A','Corrected (adjusted) calcium formula: Corrected Ca2+ = measured total Ca2+ + 0.02 x (40 - actual albumin [g/L]). Albumin is the main calcium-binding protein (~40% of total calcium). Hypoalbuminaemia reduces total calcium without affecting ionised (physiologically active) calcium -- giving a misleadingly low total calcium. Example: measured Ca2+ 2.0, albumin 20 g/L -- corrected = 2.0 + 0.02x(40-20) = 2.0 + 0.4 = 2.4 mmol/L (actually normal). Direct ionised calcium (blood gas) is the gold standard especially in acid-base disorders.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Endocrinology','Clinicals','Calcium Disorders','medium','mcq','A patient with squamous cell lung cancer develops hypercalcaemia (Ca2+ 3.2 mmol/L) with suppressed PTH and elevated PTHrP. Which mechanism is responsible?','["A. Direct bone destruction at metastatic sites releasing calcium into the bloodstream","B. Humoral hypercalcaemia of malignancy (HHM) -- PTHrP mimics PTH at the PTH/PTHrP receptor","C. Ectopic PTH secretion directly from the tumour cells","D. Excess 1,25-dihydroxyvitamin D production by the tumour"]','B','Humoral hypercalcaemia of malignancy (HHM): PTHrP (parathyroid hormone-related protein) secreted by squamous cell carcinomas (lung, head/neck, oesophagus), renal, breast, and bladder cancers binds the PTH/PTHrP receptor (PTH1R) with equal affinity to PTH causing: bone resorption (via RANKL), increased renal calcium reabsorption, reduced phosphate reabsorption. PTH is SUPPRESSED by hypercalcaemia. PTHrP is NOT detected by standard PTH assays -- requires specific PTHrP immunoassay. HHM accounts for ~80% of malignancy-related hypercalcaemia.','universal',true,'{year1,year2,year3,year4,year5,year6,practitioner}',Harrison''s Principles of Internal Medicine 20th Ed);
